    AutocommitPeriod.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: AutocommitPeriodType, location_name: 'Type', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Defines the type of time for the autocommit period of a file in an FSx for ONTAP SnapLock volume. \n        Setting this value to <code>NONE</code> disables autocommit. The default value is <code>NONE</code>. </p>", "smithy.api#required" => {}}))
    AutocommitPeriod.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: AutocommitPeriodValue, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>Defines the amount of time for the autocommit period of a file in an FSx for ONTAP SnapLock volume. \n        The following ranges are valid: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>Minutes</code>: 5 - 65,535</p>\n            </li>\n            <li>\n               <p>\n                  <code>Hours</code>: 1 - 65,535</p>\n            </li>\n            <li>\n               <p>\n                  <code>Days</code>: 1 - 3,650</p>\n            </li>\n            <li>\n               <p>\n                  <code>Months</code>: 1 - 120</p>\n            </li>\n            <li>\n               <p>\n                  <code>Years</code>: 1 - 10</p>\n            </li>\n         </ul>"}))
