    CompletionReport.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'Enabled', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Set <code>Enabled</code> to <code>True</code> to generate a <code>CompletionReport</code> when the task completes. \n            If set to <code>true</code>, then you need to provide a report <code>Scope</code>, <code>Path</code>, and <code>Format</code>. \n            Set <code>Enabled</code> to <code>False</code> if you do not want a <code>CompletionReport</code> generated when the task completes.</p>", "smithy.api#required" => {}}))
    CompletionReport.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: ArchivePath, location_name: 'Path', traits: {"smithy.api#documentation" => "<p>Required if <code>Enabled</code> is set to <code>true</code>. Specifies the location of the report on the file system's\n            linked S3 data repository. An absolute path that defines where the completion report will be stored in the destination location. \n            The <code>Path</code> you provide must be located within the file system’s ExportPath. \n            An example <code>Path</code> value is \"s3://amzn-s3-demo-bucket/myExportPath/optionalPrefix\".\n            The report provides the following information for each file in the report:\n            FilePath, FileStatus, and ErrorCode.</p>"}))
    CompletionReport.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: ReportFormat, location_name: 'Format', traits: {"smithy.api#documentation" => "<p>Required if <code>Enabled</code> is set to <code>true</code>. Specifies the format of the <code>CompletionReport</code>. <code>REPORT_CSV_20191124</code> is the only format currently supported.\n            When <code>Format</code> is set to <code>REPORT_CSV_20191124</code>, the <code>CompletionReport</code> is provided in CSV format, and is delivered to\n            <code>{path}/task-{id}/failures.csv</code>. \n        </p>"}))
    CompletionReport.add_member(:scope, Smithy::Schema::Shapes::ShapeRef.new(shape: ReportScope, location_name: 'Scope', traits: {"smithy.api#documentation" => "<p>Required if <code>Enabled</code> is set to <code>true</code>. Specifies the scope of the <code>CompletionReport</code>; <code>FAILED_FILES_ONLY</code> is the only scope currently supported. \n            When <code>Scope</code> is set to <code>FAILED_FILES_ONLY</code>, the <code>CompletionReport</code> only contains information about files that the data repository task failed to process.</p>"}))
