    CopyBackupRequest.add_member(:source_region, Smithy::Schema::Shapes::ShapeRef.new(shape: Region, location_name: 'SourceRegion', traits: {"smithy.api#documentation" => "<p>The source Amazon Web Services Region of the backup. Specifies the Amazon Web Services Region from which the backup is being copied. The source and destination\n         Regions must be in the same Amazon Web Services partition. If you don't specify a\n         Region, <code>SourceRegion</code> defaults to the Region where the request is sent from\n         (in-Region copy).</p>"}))
