    CopySnapshotAndUpdateVolumeRequest.add_member(:volume_id, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeId, location_name: 'VolumeId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the ID of the volume that you are copying the snapshot to.</p>", "smithy.api#required" => {}}))
    CopySnapshotAndUpdateVolumeRequest.add_member(:source_snapshot_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceARN, location_name: 'SourceSnapshotARN', traits: {"smithy.api#clientOptional" => {}, "smithy.api#required" => {}}))
    CopySnapshotAndUpdateVolumeRequest.add_member(:copy_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSCopyStrategy, location_name: 'CopyStrategy', traits: {"smithy.api#documentation" => "<p>Specifies the strategy to use when copying data from a snapshot to the volume. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>FULL_COPY</code> - Copies all data from the snapshot to the volume.\n                </p>\n            </li>\n            <li>\n               <p>\n                  <code>INCREMENTAL_COPY</code> - Copies only the snapshot data that's changed\n                    since the previous replication.</p>\n            </li>\n         </ul>\n         <note>\n            <p>\n               <code>CLONE</code> isn't a valid copy strategy option for the\n                    <code>CopySnapshotAndUpdateVolume</code> operation.</p>\n         </note>"}))
    CopySnapshotAndUpdateVolumeRequest.add_member(:options, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateOpenZFSVolumeOptions, location_name: 'Options', traits: {"smithy.api#documentation" => "<p>Confirms that you want to delete data on the destination volume that wasn’t there\n            during the previous snapshot replication.</p>\n         <p>Your replication will fail if you don’t include an option for a specific type of data\n            and that data is on your destination. For example, if you don’t include\n                <code>DELETE_INTERMEDIATE_SNAPSHOTS</code> and there are intermediate snapshots on\n            the destination, you can’t copy the snapshot.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DELETE_INTERMEDIATE_SNAPSHOTS</code> - Deletes snapshots on the\n                    destination volume that aren’t on the source volume.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETE_CLONED_VOLUMES</code> - Deletes snapshot clones on the\n                    destination volume that aren't on the source volume.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETE_INTERMEDIATE_DATA</code> - Overwrites snapshots on the\n                    destination volume that don’t match the source snapshot that you’re\n                    copying.</p>\n            </li>\n         </ul>"}))
    CopySnapshotAndUpdateVolumeRequest.type = Types::CopySnapshotAndUpdateVolumeRequest
    CopySnapshotAndUpdateVolumeResponse.add_member(:volume_id, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeId, location_name: 'VolumeId', traits: {"smithy.api#documentation" => "<p>The ID of the volume that you copied the snapshot to.</p>"}))
    CopySnapshotAndUpdateVolumeResponse.add_member(:lifecycle, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeLifecycle, location_name: 'Lifecycle', traits: {"smithy.api#documentation" => "<p>The lifecycle state of the destination volume. </p>"}))
