    CreateDataRepositoryTaskRequest.add_member(:release_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ReleaseConfiguration, location_name: 'ReleaseConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration that specifies the last accessed time criteria for files\n            that will be released from an Amazon FSx for Lustre file system.</p>"}))
