    CreateFileCacheLustreConfiguration.add_member(:metadata_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FileCacheLustreMetadataConfiguration, location_name: 'MetadataConfiguration', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The configuration for a Lustre MDT (Metadata Target) storage volume.</p>", "smithy.api#required" => {}}))
    CreateFileCacheLustreConfiguration.type = Types::CreateFileCacheLustreConfiguration
    CreateFileCacheRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>An idempotency token for resource creation, in a string of up to 63\n            ASCII characters. This token is automatically filled on your behalf when you use the\n            Command Line Interface (CLI) or an Amazon Web Services SDK.</p>\n         <p>By using the idempotent operation, you can retry a <code>CreateFileCache</code>\n            operation without the risk of creating an extra cache. This approach can be useful\n            when an initial call fails in a way that makes it unclear whether a cache was created.\n            Examples are if a transport level timeout occurred, or your connection was reset.\n            If you use the same client request token and the initial call created a cache, the\n            client receives success as long as the parameters are the same.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateFileCacheRequest.add_member(:file_cache_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FileCacheType, location_name: 'FileCacheType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of cache that you're creating, which\n            must be <code>LUSTRE</code>.</p>", "smithy.api#required" => {}}))
    CreateFileCacheRequest.add_member(:file_cache_type_version, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemTypeVersion, location_name: 'FileCacheTypeVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets the Lustre version for the cache that you're creating,\n            which must be <code>2.12</code>.</p>", "smithy.api#required" => {}}))
    CreateFileCacheRequest.add_member(:storage_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacity, location_name: 'StorageCapacity', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The storage capacity of the cache in gibibytes (GiB). Valid values\n            are 1200 GiB, 2400 GiB, and increments of 2400 GiB.</p>", "smithy.api#required" => {}}))
    CreateFileCacheRequest.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetIds, location_name: 'SubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#required" => {}}))
    CreateFileCacheRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIds, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of IDs specifying the security groups to apply to all network interfaces\n            created for Amazon File Cache access. This list isn't returned in later requests to\n            describe the cache.</p>"}))
    CreateFileCacheRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags'))
    CreateFileCacheRequest.add_member(:copy_tags_to_data_repository_associations, Smithy::Schema::Shapes::ShapeRef.new(shape: CopyTagsToDataRepositoryAssociations, location_name: 'CopyTagsToDataRepositoryAssociations', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags for the cache should be copied to\n            data repository associations. This value defaults to false.</p>"}))
    CreateFileCacheRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>Specifies the ID of the Key Management Service (KMS) key to use for encrypting data on\n            an Amazon File Cache. If a <code>KmsKeyId</code> isn't specified, the Amazon FSx-managed\n            KMS key for your account is used. For more information,\n            see <a href=\"https://docs.aws.amazon.com/kms/latest/APIReference/API_Encrypt.html\">Encrypt</a> in the\n            <i>Key Management Service API Reference</i>.</p>"}))
    CreateFileCacheRequest.add_member(:lustre_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileCacheLustreConfiguration, location_name: 'LustreConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration for the Amazon File Cache resource being created.</p>"}))
    CreateFileCacheRequest.add_member(:data_repository_associations, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileCacheDataRepositoryAssociations, location_name: 'DataRepositoryAssociations', traits: {"smithy.api#documentation" => "<p>A list of up to 8 configurations for data repository associations (DRAs) to\n            be created during the cache creation. The DRAs link the cache to either an\n            Amazon S3 data repository or a Network File System (NFS) data repository that supports the NFSv3 protocol.</p>\n         <p>The DRA configurations must meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>All configurations on the list must be of the\n                same data repository type, either all S3 or all NFS. A cache\n                can't link to different data repository types at the same time.</p>\n            </li>\n            <li>\n               <p>An NFS DRA must link to an NFS file system that\n                supports the NFSv3 protocol.</p>\n            </li>\n         </ul>\n         <p>DRA automatic import and automatic export is not supported.</p>"}))
    CreateFileCacheRequest.type = Types::CreateFileCacheRequest
    CreateFileCacheResponse.add_member(:file_cache, Smithy::Schema::Shapes::ShapeRef.new(shape: FileCacheCreating, location_name: 'FileCache', traits: {"smithy.api#documentation" => "<p>A description of the cache that was created.</p>"}))
    CreateFileCacheResponse.type = Types::CreateFileCacheResponse
    CreateFileSystemFromBackupRequest.add_member(:backup_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BackupId, location_name: 'BackupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#required" => {}}))
    CreateFileSystemFromBackupRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>A string of up to 63 ASCII characters that Amazon FSx uses to ensure\n            idempotent creation. This string is automatically filled on your behalf when you use the\n                Command Line Interface (CLI) or an Amazon Web Services SDK.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateFileSystemFromBackupRequest.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetIds, location_name: 'SubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the IDs of the subnets that the file system will be accessible from. For Windows <code>MULTI_AZ_1</code> \n            file system deployment types, provide exactly two subnet IDs, one for the preferred file server \n            and one for the standby file server. You specify one of these subnets as the preferred subnet \n            using the <code>WindowsConfiguration > PreferredSubnetID</code> property.</p>\n         <p>Windows <code>SINGLE_AZ_1</code> and <code>SINGLE_AZ_2</code> file system deployment\n            types, Lustre file systems, and OpenZFS file systems provide exactly one subnet ID. The\n            file server is launched in that subnet's Availability Zone.</p>", "smithy.api#required" => {}}))
    CreateFileSystemFromBackupRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIds, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of IDs for the security groups that apply to the specified network interfaces\n            created for file system access. These security groups apply to all network interfaces.\n            This value isn't returned in later <code>DescribeFileSystem</code> requests.</p>"}))
    CreateFileSystemFromBackupRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to be applied to the file system at file system creation. The key value of\n            the <code>Name</code> tag appears in the console as the file system\n            name.</p>"}))
    CreateFileSystemFromBackupRequest.add_member(:windows_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemWindowsConfiguration, location_name: 'WindowsConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration for this Microsoft Windows file system.</p>"}))
    CreateFileSystemFromBackupRequest.add_member(:lustre_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemLustreConfiguration, location_name: 'LustreConfiguration'))
    CreateFileSystemFromBackupRequest.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageType, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Sets the storage type for the Windows, OpenZFS, or Lustre file system that you're creating from\n            a backup. Valid values are <code>SSD</code>, <code>HDD</code>, and <code>INTELLIGENT_TIERING</code>.</p>\n         <ul>\n            <li>\n               <p>Set to <code>SSD</code> to use solid state drive storage. SSD is supported on all Windows and OpenZFS\n                    deployment types.</p>\n            </li>\n            <li>\n               <p>Set to <code>HDD</code> to use hard disk drive storage. \n                    HDD is supported on <code>SINGLE_AZ_2</code> and <code>MULTI_AZ_1</code> FSx for Windows File Server file system deployment types.</p>\n            </li>\n            <li>\n               <p>Set to <code>INTELLIGENT_TIERING</code> to use fully elastic, intelligently-tiered storage.\n                    Intelligent-Tiering is only available for OpenZFS file systems with the Multi-AZ deployment type\n                    and for Lustre file systems with the Persistent_2 deployment type.</p>\n            </li>\n         </ul>\n         <p> The default value is <code>SSD</code>. </p>\n         <note>\n            <p>HDD and SSD storage types have different minimum storage capacity requirements. \n            A restored file system's storage capacity is tied to the file system that was backed up. \n            You can create a file system that uses HDD storage from a backup of a file system that \n            used SSD storage if the original SSD file system had a storage capacity of at least 2000 GiB.</p>\n         </note>"}))
    CreateFileSystemFromBackupRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId'))
    CreateFileSystemFromBackupRequest.add_member(:file_system_type_version, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemTypeVersion, location_name: 'FileSystemTypeVersion', traits: {"smithy.api#documentation" => "<p>Sets the version for the Amazon FSx for Lustre file system that you're\n            creating from a backup. Valid values are <code>2.10</code>, <code>2.12</code>,\n            and <code>2.15</code>.</p>\n         <p>You can enter a Lustre version that is newer than the backup's\n            <code>FileSystemTypeVersion</code> setting. If you don't enter a newer Lustre version,\n            it defaults to the backup's setting.</p>"}))
    CreateFileSystemFromBackupRequest.add_member(:open_zfs_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemOpenZFSConfiguration, location_name: 'OpenZFSConfiguration', traits: {"smithy.api#documentation" => "<p>The OpenZFS configuration for the file system that's being created. </p>"}))
    CreateFileSystemFromBackupRequest.add_member(:storage_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacity, location_name: 'StorageCapacity', traits: {"smithy.api#documentation" => "<p>Sets the storage capacity of the OpenZFS file system that you're creating\n            from a backup, in gibibytes (GiB). Valid values are from 64 GiB up to 524,288 GiB\n            (512 TiB). However, the value that you specify must be equal to or greater than the\n            backup's storage capacity value. If you don't use the <code>StorageCapacity</code>\n            parameter, the default is the backup's <code>StorageCapacity</code> value.</p>\n         <p>If used to create a file system other than OpenZFS, you must provide a value\n            that matches the backup's <code>StorageCapacity</code> value. If you provide any\n            other value, Amazon FSx responds with an HTTP status code 400 Bad Request. </p>"}))
    CreateFileSystemFromBackupRequest.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkType, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>Sets the network type for the Amazon FSx for OpenZFS file system\n            that you're creating from a backup.</p>"}))
    CreateFileSystemFromBackupRequest.type = Types::CreateFileSystemFromBackupRequest
    CreateFileSystemFromBackupResponse.add_member(:file_system, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystem, location_name: 'FileSystem', traits: {"smithy.api#documentation" => "<p>A description of the file system.</p>"}))
    CreateFileSystemFromBackupResponse.type = Types::CreateFileSystemFromBackupResponse
    CreateFileSystemLustreConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>(Optional) The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone, where d is the weekday number, from 1 through 7, beginning with Monday and ending with Sunday.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:import_path, Smithy::Schema::Shapes::ShapeRef.new(shape: ArchivePath, location_name: 'ImportPath', traits: {"smithy.api#documentation" => "<p>(Optional) The path to the Amazon S3 bucket (including the optional prefix) that\n            you're using as the data repository for your Amazon FSx for Lustre file system.\n            The root of your FSx for Lustre file system will\n            be mapped to the root of the Amazon S3 bucket you select. An\n            example is <code>s3://import-bucket/optional-prefix</code>. If you specify a prefix\n            after the Amazon S3 bucket name, only object keys with that prefix are loaded into the\n            file system.</p>\n         <note>\n            <p>This parameter is not supported for file systems with a data repository association.</p>\n         </note>"}))
    CreateFileSystemLustreConfiguration.add_member(:export_path, Smithy::Schema::Shapes::ShapeRef.new(shape: ArchivePath, location_name: 'ExportPath', traits: {"smithy.api#documentation" => "<p>(Optional) Specifies the path in the Amazon S3 bucket where the root of your\n            Amazon FSx file system is exported. The path must use the same Amazon S3\n            bucket as specified in ImportPath. You can provide an optional prefix to which new and\n            changed data is to be exported from your Amazon FSx for Lustre file system. If\n            an <code>ExportPath</code> value is not provided, Amazon FSx sets a default export path,\n            <code>s3://import-bucket/FSxLustre[creation-timestamp]</code>. The timestamp is in\n            UTC format, for example\n            <code>s3://import-bucket/FSxLustre20181105T222312Z</code>.</p>\n         <p>The Amazon S3 export bucket must be the same as the import bucket specified by\n                <code>ImportPath</code>. If you specify only a bucket name, such as\n                <code>s3://import-bucket</code>, you get a 1:1 mapping of file system objects to S3\n            bucket objects. This mapping means that the input data in S3 is overwritten on export.\n            If you provide a custom prefix in the export path, such as\n            <code>s3://import-bucket/[custom-optional-prefix]</code>, Amazon FSx exports the contents of your file \n            system to that export prefix in the Amazon S3 bucket.</p>\n         <note>\n            <p>This parameter is not supported for file systems with a data repository association.</p>\n         </note>"}))
    CreateFileSystemLustreConfiguration.add_member(:imported_file_chunk_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Megabytes, location_name: 'ImportedFileChunkSize', traits: {"smithy.api#documentation" => "<p>(Optional) For files imported from a data repository, this value determines the stripe\n            count and maximum amount of data per file (in MiB) stored on a single physical disk. The\n            maximum number of disks that a single file can be striped across is limited by the total\n            number of disks that make up the file system.</p>\n         <p>The default chunk size is 1,024 MiB (1 GiB) and can go as high as 512,000 MiB (500\n            GiB). Amazon S3  objects have a maximum size of 5 TB.</p>\n         <note>\n            <p>This parameter is not supported for file systems with a data repository association.</p>\n         </note>"}))
    CreateFileSystemLustreConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>(Optional) Choose <code>SCRATCH_1</code> and <code>SCRATCH_2</code> deployment \n            types when you need temporary storage and shorter-term processing of data. \n            The <code>SCRATCH_2</code> deployment type provides in-transit encryption of data and higher burst \n            throughput capacity than <code>SCRATCH_1</code>.</p>\n         <p>Choose <code>PERSISTENT_1</code> for longer-term storage and for throughput-focused \n            workloads that aren’t latency-sensitive.\n            <code>PERSISTENT_1</code> supports encryption of data in transit, and is available in all \n            Amazon Web Services Regions in which FSx for Lustre is available.</p>\n         <p>Choose <code>PERSISTENT_2</code> for longer-term storage and for latency-sensitive workloads \n            that require the highest levels of IOPS/throughput. <code>PERSISTENT_2</code> supports \n            the SSD and Intelligent-Tiering storage classes.\n            You can optionally specify a metadata configuration mode for <code>PERSISTENT_2</code>\n            which supports increasing metadata performance. <code>PERSISTENT_2</code> is available\n            in a limited number of Amazon Web Services Regions. For more information, and an up-to-date\n            list of Amazon Web Services Regions in which <code>PERSISTENT_2</code> is available, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/using-fsx-lustre.html\">Deployment and\n                storage class options for FSx for Lustre file systems</a> in\n            the <i>Amazon FSx for Lustre User Guide</i>.</p>\n         <note>\n            <p>If you choose <code>PERSISTENT_2</code>, and you set <code>FileSystemTypeVersion</code> to\n                    <code>2.10</code>, the <code>CreateFileSystem</code> operation fails.</p>\n         </note>\n         <p>Encryption of data in transit is automatically turned on when you access\n                <code>SCRATCH_2</code>, <code>PERSISTENT_1</code>, and <code>PERSISTENT_2</code> file\n                systems from Amazon EC2 instances that support automatic encryption in\n                the Amazon Web Services Regions where they are available. For more information about\n                encryption in transit for FSx for Lustre file systems, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/encryption-in-transit-fsxl.html\">Encrypting data in\n                transit</a> in the <i>Amazon FSx for Lustre User Guide</i>.</p>\n         <p>(Default = <code>SCRATCH_1</code>)</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:auto_import_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoImportPolicyType, location_name: 'AutoImportPolicy', traits: {"smithy.api#documentation" => "<p> (Optional) When you create your file system, your existing S3 objects appear as file and\n            directory listings.  Use this parameter to choose how Amazon FSx keeps your file and directory\n            listings up to date as you add or modify objects in your linked S3 bucket. <code>AutoImportPolicy</code>\n            can have the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - (Default) AutoImport is off. Amazon FSx only updates \n                file and directory listings from the linked S3 bucket \n                when the file system is created. FSx does not update file and directory \n                listings for any new or changed objects after choosing this option.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW</code> - AutoImport is on. Amazon FSx automatically imports\n                directory listings of any new objects added to the linked S3 bucket that \n                do not currently exist in the FSx file system. </p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_CHANGED</code> - AutoImport is on. Amazon FSx automatically imports \n                file and directory listings of any new objects added to the S3 bucket and any \n                existing objects that are changed in the S3 bucket after you choose this option.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_CHANGED_DELETED</code> - AutoImport is on. Amazon FSx automatically\n                imports file and directory listings of any new objects added to the S3 bucket, any \n                existing objects that are changed in the S3 bucket, and any objects that were deleted\n                in the S3 bucket.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/older-deployment-types.html#legacy-auto-import-from-s3\">\n            Automatically import updates from your S3 bucket</a>.</p>\n         <note>\n            <p>This parameter is not supported for file systems with a data repository association.</p>\n         </note>"}))
    CreateFileSystemLustreConfiguration.add_member(:per_unit_storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: PerUnitStorageThroughput, location_name: 'PerUnitStorageThroughput', traits: {"smithy.api#documentation" => "<p>Required with <code>PERSISTENT_1</code> and <code>PERSISTENT_2</code> deployment\n            types using an SSD or HDD storage class, provisions the amount of read and write throughput for each 1 tebibyte (TiB) of\n            file system storage capacity, in MB/s/TiB. File system throughput capacity is calculated\n            by multiplying ﬁle system storage capacity (TiB) by the\n                <code>PerUnitStorageThroughput</code> (MB/s/TiB). For a 2.4-TiB ﬁle system,\n            provisioning 50 MB/s/TiB of <code>PerUnitStorageThroughput</code> yields 120 MB/s of ﬁle\n            system throughput. You pay for the amount of throughput that you provision. </p>\n         <p>Valid values:</p>\n         <ul>\n            <li>\n               <p>For <code>PERSISTENT_1</code> SSD storage: 50, 100, 200 MB/s/TiB.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_1</code> HDD storage: 12, 40 MB/s/TiB.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_2</code> SSD storage: 125, 250, 500, 1000 MB/s/TiB.</p>\n            </li>\n         </ul>"}))
    CreateFileSystemLustreConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    CreateFileSystemLustreConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays', traits: {"smithy.api#documentation" => "<p>The number of days to retain automatic backups. Setting this property to\n            <code>0</code> disables automatic backups. You can retain automatic backups for a\n            maximum of 90 days. The default is <code>0</code>.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>(Optional) Not available for use with file systems that are linked to a data\n            repository. A boolean flag indicating whether tags for the file system should be copied\n            to backups. The default value is false. If <code>CopyTagsToBackups</code> is set to\n            true, all file system tags are copied to all automatic and user-initiated backups when\n            the user doesn't specify any backup-specific tags. If\n                <code>CopyTagsToBackups</code> is set to true and you specify one or more backup\n            tags, only the specified tags are copied to backups. If you specify one or more tags\n            when creating a user-initiated backup, no tags are copied from the file system,\n            regardless of this value.</p>\n         <p>(Default = <code>false</code>)</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/using-backups-fsx.html\">\n            Working with backups</a> in the <i>Amazon FSx for Lustre User Guide</i>.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:drive_cache_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DriveCacheType, location_name: 'DriveCacheType', traits: {"smithy.api#documentation" => "<p>The type of drive cache used by <code>PERSISTENT_1</code> file systems that are provisioned with\n            HDD storage devices. This parameter is required when storage type is HDD. Set this property to\n            <code>READ</code> to improve the performance for frequently accessed files by caching up to 20%\n            of the total storage capacity of the file system.</p>\n         <p>This parameter is required when <code>StorageType</code> is set to <code>HDD</code>.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Sets the data compression configuration for the file system. <code>DataCompressionType</code>\n            can have the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - (Default) Data compression is turned off when\n                the file system is created.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Data compression is turned on with the LZ4\n                algorithm.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/data-compression.html\">Lustre data compression</a> \n            in the <i>Amazon FSx for Lustre User Guide</i>.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:efa_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'EfaEnabled', traits: {"smithy.api#documentation" => "<p>(Optional) Specifies whether Elastic Fabric Adapter (EFA) and GPUDirect Storage (GDS)\n            support is enabled for the Amazon FSx for Lustre file system.</p>\n         <p>(Default = <code>false</code>)</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreLogCreateConfiguration, location_name: 'LogConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre logging configuration used when creating an Amazon FSx for Lustre\n            file system. When logging is enabled, Lustre logs error and warning events for data repositories\n            associated with your file system to Amazon CloudWatch Logs.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:root_squash_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreRootSquashConfiguration, location_name: 'RootSquashConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre root squash configuration used when creating an Amazon FSx for Lustre\n            file system. When enabled, root squash restricts root-level access from clients that\n            try to access your file system as a root user.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:metadata_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemLustreMetadataConfiguration, location_name: 'MetadataConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre metadata performance configuration for the creation of an\n            FSx for Lustre file system using a <code>PERSISTENT_2</code>\n            deployment type.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityMbps, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>Specifies the throughput of an FSx for Lustre file system using the Intelligent-Tiering storage class,\n            measured in megabytes per second (MBps). Valid values are 4000 MBps or\n            multiples of 4000 MBps. You pay for the amount of throughput that you provision.</p>"}))
    CreateFileSystemLustreConfiguration.add_member(:data_read_cache_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreReadCacheConfiguration, location_name: 'DataReadCacheConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the optional provisioned SSD read cache on FSx for Lustre file systems that\n            use the Intelligent-Tiering storage class. Required when <code>StorageType</code> is set\n            to <code>INTELLIGENT_TIERING</code>.</p>"}))
    CreateFileSystemLustreConfiguration.type = Types::CreateFileSystemLustreConfiguration
    CreateFileSystemLustreMetadataConfiguration.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: MetadataIops, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>(USER_PROVISIONED mode only) Specifies the number of Metadata IOPS to provision\n            for the file system. This parameter sets the maximum rate of metadata disk IOPS\n            supported by the file system.</p>\n         <ul>\n            <li>\n               <p>For SSD file systems, valid values are <code>1500</code>,\n                    <code>3000</code>, <code>6000</code>, <code>12000</code>, and\n                    multiples of <code>12000</code> up to a maximum of <code>192000</code>.</p>\n            </li>\n            <li>\n               <p>For Intelligent-Tiering file systems, valid values are <code>6000</code>\n                    and <code>12000</code>.</p>\n            </li>\n         </ul>\n         <note>\n            <p>\n               <code>Iops</code> doesn’t have a default value. If you're using USER_PROVISIONED mode,\n                you can choose to specify a valid value. If you're using AUTOMATIC mode,\n                you cannot specify a value because FSx for Lustre automatically sets\n                the value based on your file system storage capacity.\n            </p>\n         </note>"}))
    CreateFileSystemLustreMetadataConfiguration.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: MetadataConfigurationMode, location_name: 'Mode', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The metadata configuration mode for provisioning Metadata IOPS for\n            an FSx for Lustre file system using a <code>PERSISTENT_2</code>\n            deployment type.</p>\n         <ul>\n            <li>\n               <p>In AUTOMATIC mode (supported only on SSD file systems),\n                    FSx for Lustre automatically provisions and scales the\n                    number of Metadata IOPS for your file system\n                based on your file system storage capacity.</p>\n            </li>\n            <li>\n               <p>In USER_PROVISIONED mode, you specify the number of Metadata\n                IOPS to provision for your file system.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateFileSystemLustreMetadataConfiguration.type = Types::CreateFileSystemLustreMetadataConfiguration
    CreateFileSystemOntapConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    CreateFileSystemOntapConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    CreateFileSystemOntapConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OntapDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the FSx for ONTAP file system deployment type to use in creating\n            the file system.  </p>\n         <ul>\n            <li>\n               <p>\n                  <code>MULTI_AZ_1</code> - A high availability file system configured\n                    for Multi-AZ redundancy to tolerate temporary Availability Zone (AZ)\n                    unavailability. This is a first-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MULTI_AZ_2</code> - A high availability file system configured for Multi-AZ redundancy to tolerate \n                temporary AZ unavailability. This is a second-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_1</code> - A file system configured for Single-AZ\n                    redundancy. This is a first-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_2</code> - A file system configured with multiple high-availability (HA) pairs for Single-AZ redundancy. \n                This is a second-generation FSx for ONTAP file system.</p>\n            </li>\n         </ul>\n         <p>For information about the use cases for Multi-AZ and Single-AZ deployments, refer to\n                <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/high-availability-AZ.html\">Choosing a file system deployment type</a>. </p>", "smithy.api#required" => {}}))
    CreateFileSystemOntapConfiguration.add_member(:endpoint_ip_address_range, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressRange, location_name: 'EndpointIpAddressRange', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the IP address range in which the endpoints to access your\n            file system will be created. By default in the Amazon FSx  API, Amazon FSx\n            selects an unused IP address range for you from the 198.19.* range. By default in the \n            Amazon FSx  console, Amazon FSx  chooses the last 64 IP addresses from\n            the VPC’s primary CIDR range to use as the endpoint IP address range for the file system.\n            You can have overlapping endpoint IP addresses for file systems deployed in the\n            same VPC/route tables, as long as they don't overlap with any subnet.</p>"}))
    CreateFileSystemOntapConfiguration.add_member(:fsx_admin_password, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminPassword, location_name: 'FsxAdminPassword', traits: {"smithy.api#documentation" => "<p>The ONTAP administrative password for the <code>fsxadmin</code> user with which you\n            administer your file system using the NetApp ONTAP CLI and REST API.</p>"}))
    CreateFileSystemOntapConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS configuration for the FSx for ONTAP file system.</p>"}))
    CreateFileSystemOntapConfiguration.add_member(:preferred_subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'PreferredSubnetId', traits: {"smithy.api#documentation" => "<p>Required when <code>DeploymentType</code> is set to <code>MULTI_AZ_1</code> or <code>MULTI_AZ_2</code>. This\n            specifies the subnet in which you want the preferred file server to be located.</p>"}))
    CreateFileSystemOntapConfiguration.add_member(:route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'RouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the route tables in which Amazon FSx  creates the rules\n            for routing traffic to the correct file server. You should specify all virtual private cloud\n            (VPC) route tables associated with the subnets in which your clients are located. By default,\n            Amazon FSx  selects your VPC's default route table.</p>\n         <note>\n            <p>Amazon FSx manages these route tables for Multi-AZ file systems using tag-based authentication. \n            These route tables are tagged with <code>Key: AmazonFSx; Value: ManagedByAmazonFSx</code>. \n            When creating FSx for ONTAP Multi-AZ file systems using CloudFormation we recommend that you add the \n            <code>Key: AmazonFSx; Value: ManagedByAmazonFSx</code> tag manually.</p>\n         </note>"}))
    CreateFileSystemOntapConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>Sets the throughput capacity for the file system that you're creating in megabytes per second (MBps). For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-throughput-capacity.html\">Managing throughput capacity</a> \n            in the FSx for ONTAP User Guide.</p>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> and <code>ThroughputCapacityPerHAPair</code> are not the same value.</p>\n            </li>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> when divided by the value of <code>HAPairs</code> is outside of the valid range for <code>ThroughputCapacity</code>.</p>\n            </li>\n         </ul>"}))
    CreateFileSystemOntapConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    CreateFileSystemOntapConfiguration.add_member(:ha_pairs, Smithy::Schema::Shapes::ShapeRef.new(shape: HAPairs, location_name: 'HAPairs', traits: {"smithy.api#documentation" => "<p>Specifies how many high-availability (HA) pairs of file servers will power your file system. First-generation file systems are powered by 1 HA pair.\n            Second-generation multi-AZ file systems are powered by 1 HA pair. Second generation single-AZ file systems are powered by up to 12 HA pairs. The default value is 1. \n            The value of this property affects the values of <code>StorageCapacity</code>, \n            <code>Iops</code>, and <code>ThroughputCapacity</code>. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/administering-file-systems.html#HA-pairs\">High-availability (HA) pairs</a> in the FSx for ONTAP user guide. Block storage protocol support \n            (iSCSI and NVMe over TCP) is disabled on file systems with more than 6 HA pairs. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/supported-fsx-clients.html#using-block-storage\">Using block storage protocols</a>. </p>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>HAPairs</code> is less than 1 or greater than 12.</p>\n            </li>\n            <li>\n               <p>The value of <code>HAPairs</code> is greater than 1 and the value of <code>DeploymentType</code> is <code>SINGLE_AZ_1</code>, <code>MULTI_AZ_1</code>, or <code>MULTI_AZ_2</code>.</p>\n            </li>\n         </ul>"}))
    CreateFileSystemOntapConfiguration.add_member(:throughput_capacity_per_ha_pair, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityPerHAPair, location_name: 'ThroughputCapacityPerHAPair', traits: {"smithy.api#documentation" => "<p>Use to choose the throughput capacity per HA pair, rather than the total throughput for the file system. </p>\n         <p>You can define either the <code>ThroughputCapacityPerHAPair</code> or the <code>ThroughputCapacity</code> when creating a file system, but not both.</p>\n         <p>This field and <code>ThroughputCapacity</code> are the same for file systems powered by one HA pair.</p>\n         <ul>\n            <li>\n               <p>For <code>SINGLE_AZ_1</code> and <code>MULTI_AZ_1</code> file systems, valid values are 128, 256, 512, 1024, 2048, or 4096 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>SINGLE_AZ_2</code>, valid values are 1536, 3072, or 6144 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>MULTI_AZ_2</code>, valid values are 384, 768, 1536, 3072, or 6144 MBps.</p>\n            </li>\n         </ul>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> and <code>ThroughputCapacityPerHAPair</code> are not the same value for file systems with one HA pair.</p>\n            </li>\n            <li>\n               <p>The value of deployment type is <code>SINGLE_AZ_2</code> and <code>ThroughputCapacity</code> / <code>ThroughputCapacityPerHAPair</code> is not a valid HA pair (a value between 1 and 12).</p>\n            </li>\n            <li>\n               <p>The value of <code>ThroughputCapacityPerHAPair</code> is not a valid value.</p>\n            </li>\n         </ul>"}))
    CreateFileSystemOntapConfiguration.type = Types::CreateFileSystemOntapConfiguration
    CreateFileSystemOpenZFSConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    CreateFileSystemOpenZFSConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the file system should be copied to\n            backups. This value defaults to <code>false</code>. If it's set to <code>true</code>,\n            all tags for the file system are copied to all automatic and user-initiated backups\n            where the user doesn't specify tags. If this value is <code>true</code>, and you specify\n            one or more tags, only the specified tags are copied to backups. If you specify one or\n            more tags when creating a user-initiated backup, no tags are copied from the file\n            system, regardless of this value.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:copy_tags_to_volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToVolumes', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the file system should be copied to volumes.\n            This value defaults to <code>false</code>. If it's set to <code>true</code>, all tags\n            for the file system are copied to volumes where the user doesn't specify tags. If this\n            value is <code>true</code>, and you specify one or more tags, only the specified tags\n            are copied to volumes. If you specify one or more tags when creating the volume, no\n            tags are copied from the file system, regardless of this value.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    CreateFileSystemOpenZFSConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the file system deployment type. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>MULTI_AZ_1</code>- Creates file systems with high availability and durability by replicating your data and supporting failover across multiple Availability Zones in the same Amazon Web Services Region.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_HA_2</code>- Creates file systems with high availability and throughput capacities of 160 - 10,240 MB/s using an NVMe L2ARC cache by deploying a primary and standby file system within the same Availability Zone.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_HA_1</code>- Creates file systems with high availability and throughput capacities of 64 - 4,096 MB/s by deploying a primary and standby file system within the same Availability Zone.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_2</code>- Creates file systems with throughput capacities of 160 - 10,240 MB/s\n                using an NVMe L2ARC cache that automatically recover within a single Availability Zone.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_1</code>- Creates file systems with throughput capacities of 64 - 4,096 MBs that automatically recover within a single Availability Zone.</p>\n            </li>\n         </ul>\n         <p>For a list of which Amazon Web Services Regions each deployment type is available in, see <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/availability-durability.html#available-aws-regions\">Deployment type availability</a>.\n            For more information on the differences in performance between deployment types, see <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance.html#zfs-fs-performance\">File system performance</a>\n            in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateFileSystemOpenZFSConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the throughput of an Amazon FSx for OpenZFS file system, measured in megabytes per second (MBps). Valid values depend on the <code>DeploymentType</code> that you choose, as follows:</p>\n         <ul>\n            <li>\n               <p>For <code>MULTI_AZ_1</code> and <code>SINGLE_AZ_2</code>, valid values are 160, 320, 640,\n                1280, 2560, 3840, 5120, 7680, or 10240 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>SINGLE_AZ_1</code>, valid values are 64, 128, 256, 512, 1024, 2048, 3072, or 4096 MBps.</p>\n            </li>\n         </ul>\n         <p>You pay for additional throughput capacity that you provision.</p>", "smithy.api#required" => {}}))
    CreateFileSystemOpenZFSConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    CreateFileSystemOpenZFSConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration'))
    CreateFileSystemOpenZFSConfiguration.add_member(:root_volume_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSCreateRootVolumeConfiguration, location_name: 'RootVolumeConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration Amazon FSx uses when creating the root value of the Amazon FSx for OpenZFS\n            file system. All volumes are children of the root volume. </p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:preferred_subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'PreferredSubnetId', traits: {"smithy.api#documentation" => "<p>Required when <code>DeploymentType</code> is set to <code>MULTI_AZ_1</code>. This specifies the subnet in which you want the preferred file server to be located.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:endpoint_ip_address_range, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressRange, location_name: 'EndpointIpAddressRange', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the IP address range in which the endpoints to access your\n            file system will be created. By default in the Amazon FSx API and Amazon FSx console, Amazon FSx\n            selects an available /28 IP address range for you from one of the VPC's CIDR ranges.\n            You can have overlapping endpoint IP addresses for file systems deployed in the\n            same VPC/route tables, as long as they don't overlap with any subnet.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:endpoint_ipv6_address_range, Smithy::Schema::Shapes::ShapeRef.new(shape: Ipv6AddressRange, location_name: 'EndpointIpv6AddressRange', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the IP address range in which the endpoints to access\n            your file system will be created. By default in the Amazon FSx API and\n            Amazon FSx console, Amazon FSx selects an available /118 IP address\n            range for you from one of the VPC's CIDR ranges. You can have overlapping endpoint\n            IP addresses for file systems deployed in the same VPC/route tables, as long as they\n            don't overlap with any subnet.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'RouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the route tables in which Amazon FSx  creates the rules\n            for routing traffic to the correct file server. You should specify all virtual private cloud\n            (VPC) route tables associated with the subnets in which your clients are located. By default,\n            Amazon FSx  selects your VPC's default route table.</p>"}))
    CreateFileSystemOpenZFSConfiguration.add_member(:read_cache_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSReadCacheConfiguration, location_name: 'ReadCacheConfiguration', traits: {"smithy.api#documentation" => "<p>\n            Specifies the optional provisioned SSD read cache on file systems that use the Intelligent-Tiering storage class. \n        </p>"}))
    CreateFileSystemOpenZFSConfiguration.type = Types::CreateFileSystemOpenZFSConfiguration
    CreateFileSystemRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>A string of up to 63 ASCII characters that Amazon FSx uses to ensure\n            idempotent creation. This string is automatically filled on your behalf when you use the\n                Command Line Interface (CLI) or an Amazon Web Services SDK.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateFileSystemRequest.add_member(:file_system_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemType, location_name: 'FileSystemType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of Amazon FSx file system to create. Valid values are\n                <code>WINDOWS</code>, <code>LUSTRE</code>, <code>ONTAP</code>, and\n                <code>OPENZFS</code>.</p>", "smithy.api#required" => {}}))
    CreateFileSystemRequest.add_member(:storage_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacity, location_name: 'StorageCapacity', traits: {"smithy.api#documentation" => "<p>Sets the storage capacity of the file system that you're creating, in gibibytes (GiB).</p>\n         <p>\n            <b>FSx for Lustre file systems</b> - The amount of\n            storage capacity that you can configure depends on the value that you set for\n                <code>StorageType</code> and the Lustre <code>DeploymentType</code>, as\n            follows:</p>\n         <ul>\n            <li>\n               <p>For <code>SCRATCH_2</code>, <code>PERSISTENT_2</code>, and <code>PERSISTENT_1</code> deployment types \n                using SSD storage type, the valid values are 1200 GiB, 2400 GiB, and increments of 2400 GiB.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_1</code> HDD file systems, valid values are increments of 6000 GiB for \n                12 MB/s/TiB file systems and increments of 1800 GiB for 40 MB/s/TiB file systems.</p>\n            </li>\n            <li>\n               <p>For <code>SCRATCH_1</code> deployment type, valid values are \n                1200 GiB, 2400 GiB, and increments of 3600 GiB.</p>\n            </li>\n         </ul>\n         <p>\n            <b>FSx for ONTAP file systems</b> - The amount of storage capacity \n            that you can configure depends on the value of the <code>HAPairs</code> property. The minimum value is calculated as 1,024 * <code>HAPairs</code> and the maximum is calculated as 524,288 * <code>HAPairs</code>. </p>\n         <p>\n            <b>FSx for OpenZFS file systems</b> - The amount of storage capacity that \n            you can configure is from 64 GiB up to 524,288 GiB (512 TiB).</p>\n         <p>\n            <b>FSx for Windows File Server file systems</b> - The amount\n            of storage capacity that you can configure depends on the value that you set for\n                <code>StorageType</code> as follows:</p>\n         <ul>\n            <li>\n               <p>For SSD storage, valid values are 32 GiB-65,536 GiB (64 TiB).</p>\n            </li>\n            <li>\n               <p>For HDD storage, valid values are 2000 GiB-65,536 GiB (64 TiB).</p>\n            </li>\n         </ul>"}))
    CreateFileSystemRequest.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageType, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Sets the storage class for the file system that you're creating. Valid values are\n                <code>SSD</code>, <code>HDD</code>, and <code>INTELLIGENT_TIERING</code>.</p>\n         <ul>\n            <li>\n               <p>Set to <code>SSD</code> to use solid state drive storage. SSD is supported on all Windows,\n                    Lustre, ONTAP, and OpenZFS deployment types.</p>\n            </li>\n            <li>\n               <p>Set to <code>HDD</code> to use hard disk drive storage, which is supported on \n                    <code>SINGLE_AZ_2</code> and <code>MULTI_AZ_1</code> Windows file system deployment types,\n                and on <code>PERSISTENT_1</code> Lustre file system deployment types.</p>\n            </li>\n            <li>\n               <p>Set to <code>INTELLIGENT_TIERING</code> to use fully elastic, intelligently-tiered storage.\n                    Intelligent-Tiering is only available for OpenZFS file systems with the Multi-AZ deployment type\n                    and for Lustre file systems with the Persistent_2 deployment type.</p>\n            </li>\n         </ul>\n         <p>Default value is <code>SSD</code>. For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/optimize-fsx-costs.html#storage-type-options\"> Storage\n                type options</a> in the <i>FSx for Windows File Server User\n                Guide</i>, <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/using-fsx-lustre.html#lustre-storage-classes\">FSx for Lustre storage classes</a>\n            in the <i>FSx for Lustre User Guide</i>, and <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance-intelligent-tiering\">Working with Intelligent-Tiering</a>\n            in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    CreateFileSystemRequest.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetIds, location_name: 'SubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the IDs of the subnets that the file system will be accessible from. For\n            Windows and ONTAP <code>MULTI_AZ_1</code> deployment types,provide exactly two subnet\n            IDs, one for the preferred file server and one for the standby file server. You specify\n            one of these subnets as the preferred subnet using the <code>WindowsConfiguration >\n                PreferredSubnetID</code> or <code>OntapConfiguration > PreferredSubnetID</code>\n            properties. For more information about Multi-AZ file system configuration, see <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/high-availability-multiAZ.html\">\n                Availability and durability: Single-AZ and Multi-AZ file systems</a> in the\n                <i>Amazon FSx for Windows User Guide</i> and <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/high-availability-multiAZ.html\">\n                Availability and durability</a> in the <i>Amazon FSx for ONTAP User\n                Guide</i>.</p>\n         <p>For Windows <code>SINGLE_AZ_1</code> and <code>SINGLE_AZ_2</code> and all Lustre \n            deployment types, provide exactly one subnet ID.\n           The file server is launched in that subnet's Availability Zone.</p>", "smithy.api#required" => {}}))
    CreateFileSystemRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIds, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of IDs specifying the security groups to apply to all network interfaces\n            created for file system access. This list isn't returned in later requests to\n            describe the file system.</p>\n         <important>\n            <p>You must specify a security group if you are creating a Multi-AZ \n            FSx for ONTAP file system in a VPC subnet that has been shared with you.</p>\n         </important>"}))
    CreateFileSystemRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to apply to the file system that's being created. The key value of the\n                <code>Name</code> tag appears in the console as the file system name.</p>"}))
    CreateFileSystemRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId'))
    CreateFileSystemRequest.add_member(:windows_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemWindowsConfiguration, location_name: 'WindowsConfiguration', traits: {"smithy.api#documentation" => "<p>The Microsoft Windows configuration for the file system that's being created.</p>"}))
    CreateFileSystemRequest.add_member(:lustre_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemLustreConfiguration, location_name: 'LustreConfiguration'))
    CreateFileSystemRequest.add_member(:ontap_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemOntapConfiguration, location_name: 'OntapConfiguration'))
    CreateFileSystemRequest.add_member(:file_system_type_version, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemTypeVersion, location_name: 'FileSystemTypeVersion', traits: {"smithy.api#documentation" => "<p>For FSx for Lustre file systems, sets the Lustre version for the file system\n            that you're creating. Valid values are <code>2.10</code>, <code>2.12</code>, and\n            <code>2.15</code>:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>2.10</code> is supported by the Scratch and Persistent_1 Lustre \n                deployment types.</p>\n            </li>\n            <li>\n               <p>\n                  <code>2.12</code> is supported by all Lustre deployment types, except\n                for <code>PERSISTENT_2</code> with a metadata configuration mode.</p>\n            </li>\n            <li>\n               <p>\n                  <code>2.15</code> is supported by all Lustre deployment types and is\n                recommended for all new file systems.</p>\n            </li>\n         </ul>\n         <p>Default value is <code>2.10</code>, except for the following deployments:</p>\n         <ul>\n            <li>\n               <p>Default value is <code>2.12</code> when <code>DeploymentType</code> is set to \n                <code>PERSISTENT_2</code> without a metadata configuration mode.</p>\n            </li>\n            <li>\n               <p>Default value is <code>2.15</code> when <code>DeploymentType</code> is set to \n                <code>PERSISTENT_2</code> with a metadata configuration mode.</p>\n            </li>\n         </ul>"}))
    CreateFileSystemRequest.add_member(:open_zfs_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFileSystemOpenZFSConfiguration, location_name: 'OpenZFSConfiguration', traits: {"smithy.api#documentation" => "<p>The OpenZFS configuration for the file system that's being created.</p>"}))
    CreateFileSystemRequest.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkType, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the Amazon FSx file system that you\n            are creating. Valid values are <code>IPV4</code> (which supports\n            IPv4 only) and <code>DUAL</code> (for dual-stack mode, which supports\n            both IPv4 and IPv6). The default is <code>IPV4</code>. Supported only\n            for Amazon FSx for OpenZFS file systems.</p>"}))
    CreateFileSystemRequest.type = Types::CreateFileSystemRequest
    CreateFileSystemResponse.add_member(:file_system, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystem, location_name: 'FileSystem', traits: {"smithy.api#documentation" => "<p>The configuration of the file system that was created.</p>"}))
    CreateFileSystemResponse.type = Types::CreateFileSystemResponse
    CreateFileSystemWindowsConfiguration.add_member(:active_directory_id, Smithy::Schema::Shapes::ShapeRef.new(shape: DirectoryId, location_name: 'ActiveDirectoryId', traits: {"smithy.api#documentation" => "<p>The ID for an existing Amazon Web Services Managed Microsoft Active Directory (AD) instance that the\n            file system should join when it's created.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:self_managed_active_directory_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SelfManagedActiveDirectoryConfiguration, location_name: 'SelfManagedActiveDirectoryConfiguration'))
    CreateFileSystemWindowsConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>Specifies the file system deployment type, valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>MULTI_AZ_1</code> - Deploys a high availability file system that is configured \n                    for Multi-AZ redundancy to tolerate temporary Availability Zone (AZ) unavailability. You \n                    can only deploy a Multi-AZ file system in Amazon Web Services Regions that have a minimum of three Availability Zones. Also \n                supports HDD storage type</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_1</code> - (Default) Choose to deploy a file system that is configured for single AZ redundancy.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_2</code> - The latest generation Single AZ file system. \n                    Specifies a file system that is configured for single AZ redundancy and supports HDD storage type.</p>\n            </li>\n         </ul>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/high-availability-multiAZ.html\">\n                Availability and Durability: Single-AZ and Multi-AZ File Systems</a>.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:preferred_subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'PreferredSubnetId', traits: {"smithy.api#documentation" => "<p>Required when <code>DeploymentType</code> is set to <code>MULTI_AZ_1</code>. This specifies the subnet \n            in which you want the preferred file server to be located. For in-Amazon Web Services applications, we recommend that you launch \n            your clients in the same Availability Zone (AZ) as your preferred file server to reduce cross-AZ \n            data transfer costs and minimize latency. </p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets the throughput capacity of an Amazon FSx file system, measured in megabytes per second (MB/s), in 2 to\n            the <i>n</i>th increments, between 2^3 (8) and 2^11 (2048).</p>", "smithy.api#required" => {}}))
    CreateFileSystemWindowsConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone, where d is the weekday number, from 1 through 7, beginning with Monday and ending with Sunday.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime', traits: {"smithy.api#documentation" => "<p>The preferred time to take daily automatic backups, formatted HH:MM in the UTC time\n            zone.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays', traits: {"smithy.api#documentation" => "<p>The number of days to retain automatic backups. Setting this property to\n            <code>0</code> disables automatic backups. You can retain automatic backups for a\n            maximum of 90 days. The default is <code>30</code>.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags for the file system should be copied to\n            backups. This value defaults to false. If it's set to true, all tags for the file\n            system are copied to all automatic and user-initiated backups where the user\n            doesn't specify tags. If this value is true, and you specify one or more tags, only\n            the specified tags are copied to backups. If you specify one or more tags when creating a\n            user-initiated backup, no tags are copied from the file system, regardless of this value.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:aliases, Smithy::Schema::Shapes::ShapeRef.new(shape: AlternateDNSNames, location_name: 'Aliases', traits: {"smithy.api#documentation" => "<p>An array of one or more DNS alias names that you want to associate with the Amazon FSx file system. \n            Aliases allow you to use existing DNS names to access the data in your Amazon FSx file system. \n            You can associate up to 50 aliases with a file system at any time. \n            You can associate additional DNS aliases after you create the file system using the AssociateFileSystemAliases operation. \n            You can remove DNS aliases from the file system after it is created using the DisassociateFileSystemAliases operation.\n            You only need to specify the alias name in the request payload.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/managing-dns-aliases.html\">Working with DNS Aliases</a> and \n        <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/walkthrough05-file-system-custom-CNAME.html\">Walkthrough 5: Using DNS aliases to access your file system</a>, including\n        additional steps you must take to be able to access your file system using a DNS alias.</p>\n         <p>An alias name has to meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>Formatted as a fully-qualified domain name (FQDN), <code>hostname.domain</code>, for example, <code>accounting.example.com</code>.</p>\n            </li>\n            <li>\n               <p>Can contain alphanumeric characters, the underscore (_), and the hyphen (-).</p>\n            </li>\n            <li>\n               <p>Cannot start or end with a hyphen.</p>\n            </li>\n            <li>\n               <p>Can start with a numeric.</p>\n            </li>\n         </ul>\n         <p>For DNS alias names, Amazon FSx stores alphabetic characters as lowercase letters (a-z), regardless of how you specify them: \n            as uppercase letters, lowercase letters, or the corresponding letters in escape codes.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:audit_log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAuditLogCreateConfiguration, location_name: 'AuditLogConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration that Amazon FSx for Windows File Server uses to audit and log\n            user accesses of files, folders, and file shares on the Amazon FSx for Windows File Server\n            file system.</p>"}))
    CreateFileSystemWindowsConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS (input/output operations per second) configuration for an Amazon FSx for Windows file system.\n        By default, Amazon FSx automatically provisions 3 IOPS per GiB of storage capacity. You can provision additional\n        IOPS per GiB of storage, up to the maximum limit associated with your chosen throughput capacity.</p>"}))
    CreateFileSystemWindowsConfiguration.type = Types::CreateFileSystemWindowsConfiguration
    CreateOntapVolumeConfiguration.add_member(:junction_path, Smithy::Schema::Shapes::ShapeRef.new(shape: JunctionPath, location_name: 'JunctionPath', traits: {"smithy.api#documentation" => "<p>Specifies the location in the SVM's namespace where the volume is mounted.\n            This parameter is required. The <code>JunctionPath</code> must have a leading\n            forward slash, such as <code>/vol3</code>.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:security_style, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityStyle, location_name: 'SecurityStyle', traits: {"smithy.api#documentation" => "<p>Specifies the security style for the volume. If a volume's security style is not specified, \n            it is automatically set to the root volume's security style. The security style determines the type of permissions \n            that FSx for ONTAP uses to control data access. Specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>UNIX</code> if the file system is managed by a UNIX\n                administrator, the majority of users are NFS clients, and an application\n                accessing the data uses a UNIX user as the service account.\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>NTFS</code> if the file system is managed by a Windows\n                administrator, the majority of users are SMB clients, and an application\n                accessing the data uses a Windows user as the service account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MIXED</code> This is an advanced setting. For more information, see the topic \n                <a href=\"https://docs.netapp.com/us-en/ontap/nfs-admin/security-styles-their-effects-concept.html\">What the security styles and their effects are</a> \n                in the NetApp Documentation Center.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-volumes.html#volume-security-style\">Volume security style</a> in the \n        FSx for ONTAP User Guide.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:size_in_megabytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacity, location_name: 'SizeInMegabytes', traits: {"smithy.api#deprecated" => {"message" => "This property is deprecated, use SizeInBytes instead"}, "smithy.api#documentation" => "<p>Use <code>SizeInBytes</code> instead. Specifies the size of the volume, in megabytes (MB), that you are creating.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:storage_efficiency_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'StorageEfficiencyEnabled', traits: {"smithy.api#documentation" => "<p>Set to true to enable deduplication, compression, and compaction storage\n            efficiency features on the volume, or set to false to disable them.</p>\n         <p>\n            <code>StorageEfficiencyEnabled</code> is required when creating a <code>RW</code> volume (<code>OntapVolumeType</code> set to <code>RW</code>).</p>"}))
    CreateOntapVolumeConfiguration.add_member(:storage_virtual_machine_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageVirtualMachineId, location_name: 'StorageVirtualMachineId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the ONTAP SVM in which to create the volume.</p>", "smithy.api#required" => {}}))
    CreateOntapVolumeConfiguration.add_member(:tiering_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: TieringPolicy, location_name: 'TieringPolicy'))
    CreateOntapVolumeConfiguration.add_member(:ontap_volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InputOntapVolumeType, location_name: 'OntapVolumeType', traits: {"smithy.api#documentation" => "<p>Specifies the type of volume you are creating. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>RW</code> specifies a read/write volume. <code>RW</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DP</code> specifies a data-protection volume. A <code>DP</code> volume\n                is read-only and can be used as the destination of a NetApp SnapMirror relationship.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-volumes.html#volume-types\">Volume types</a> \n            in the Amazon FSx for NetApp ONTAP User Guide.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:snapshot_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotPolicy, location_name: 'SnapshotPolicy', traits: {"smithy.api#documentation" => "<p>Specifies the snapshot policy for the volume. There are three built-in snapshot policies:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code>: This is the default policy. A maximum of six hourly snapshots taken five minutes past \n            the hour. A maximum of two daily snapshots taken Monday through Saturday at 10 minutes after\n            midnight. A maximum of two weekly snapshots taken every Sunday at 15 minutes after midnight.</p>\n            </li>\n            <li>\n               <p>\n                  <code>default-1weekly</code>: This policy is the same as the <code>default</code> policy except \n            that it only retains one snapshot from the weekly schedule.</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code>: This policy does not take any snapshots. This policy can be assigned to volumes to \n            prevent automatic snapshots from being taken.</p>\n            </li>\n         </ul>\n         <p>You can also provide the name of a custom policy that you created with the ONTAP CLI or REST API.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snapshots-ontap.html#snapshot-policies\">Snapshot policies</a> \n            in the Amazon FSx for NetApp ONTAP User Guide.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags for the volume should be copied to backups. This value defaults to\n            false. If it's set to true, all tags for the volume are copied to all automatic and user-initiated backups\n            where the user doesn't specify tags. If this value is true, and you specify one or more tags, only the\n            specified tags are copied to backups. If you specify one or more tags when creating a user-initiated\n            backup, no tags are copied from the volume, regardless of this value.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:snaplock_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateSnaplockConfiguration, location_name: 'SnaplockConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the SnapLock configuration for an FSx for ONTAP volume. </p>"}))
    CreateOntapVolumeConfiguration.add_member(:volume_style, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeStyle, location_name: 'VolumeStyle', traits: {"smithy.api#documentation" => "<p>Use to specify the style of an ONTAP volume. FSx for ONTAP offers two styles of volumes that you can use for different purposes, \n            FlexVol and FlexGroup volumes. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-volumes.html#volume-styles\">Volume styles</a> in the Amazon FSx for NetApp ONTAP User Guide.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:aggregate_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateAggregateConfiguration, location_name: 'AggregateConfiguration', traits: {"smithy.api#documentation" => "<p>Use to specify configuration options for a volume’s storage aggregate or aggregates.</p>"}))
    CreateOntapVolumeConfiguration.add_member(:size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacityBytes, location_name: 'SizeInBytes', traits: {"smithy.api#documentation" => "<p>Specifies the configured size of the volume, in bytes.</p>"}))
    CreateOntapVolumeConfiguration.type = Types::CreateOntapVolumeConfiguration
    CreateOpenZFSOriginSnapshotConfiguration.add_member(:snapshot_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceARN, location_name: 'SnapshotARN', traits: {"smithy.api#clientOptional" => {}, "smithy.api#required" => {}}))
    CreateOpenZFSOriginSnapshotConfiguration.add_member(:copy_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSCopyStrategy, location_name: 'CopyStrategy', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the strategy used when copying data from the snapshot to the new volume. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>CLONE</code> - The new volume references the data in the origin\n                    snapshot. Cloning a snapshot is faster than copying data from the snapshot to a\n                    new volume and doesn't consume disk throughput. However, the origin snapshot\n                    can't be deleted if there is a volume using its copied data.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FULL_COPY</code> - Copies all data from the snapshot to the new\n                    volume.</p>\n               <p>Specify this option to create the volume from a snapshot on another FSx for OpenZFS file system.</p>\n            </li>\n         </ul>\n         <note>\n            <p>The <code>INCREMENTAL_COPY</code> option is only for updating an existing volume\n                by using a snapshot from another FSx for OpenZFS file system. For more\n                information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/APIReference/API_CopySnapshotAndUpdateVolume.html\">CopySnapshotAndUpdateVolume</a>.</p>\n         </note>", "smithy.api#required" => {}}))
    CreateOpenZFSOriginSnapshotConfiguration.type = Types::CreateOpenZFSOriginSnapshotConfiguration
    CreateOpenZFSVolumeConfiguration.add_member(:parent_volume_id, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeId, location_name: 'ParentVolumeId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the volume to use as the parent volume of the volume that you are creating.</p>", "smithy.api#required" => {}}))
    CreateOpenZFSVolumeConfiguration.add_member(:storage_capacity_reservation_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerNoMaxFromNegativeOne, location_name: 'StorageCapacityReservationGiB', traits: {"smithy.api#documentation" => "<p>Specifies the amount of storage in gibibytes (GiB) to reserve from the parent volume. Setting\n            <code>StorageCapacityReservationGiB</code> guarantees that the specified amount of storage space\n            on the parent volume will always be available for the volume. \n            You can't reserve more storage than the parent volume has. To <i>not</i> specify a storage capacity \n            reservation, set this to <code>0</code> or <code>-1</code>. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/managing-volumes.html#volume-properties\">Volume properties</a> \n            in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:storage_capacity_quota_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerNoMaxFromNegativeOne, location_name: 'StorageCapacityQuotaGiB', traits: {"smithy.api#documentation" => "<p>Sets the maximum storage size in gibibytes (GiB) for the volume. You can specify \n            a quota that is larger than the storage on the parent volume. A volume quota limits \n            the amount of storage that the volume can consume to the configured amount, but does not \n            guarantee the space will be available on the parent volume. To guarantee quota space, you must also set \n            <code>StorageCapacityReservationGiB</code>. To <i>not</i> specify a storage capacity quota, set this to <code>-1</code>.\n        </p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/managing-volumes.html#volume-properties\">Volume properties</a> \n            in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:record_size_ki_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerRecordSizeKiB, location_name: 'RecordSizeKiB', traits: {"smithy.api#documentation" => "<p>Specifies the suggested block size for a volume in a ZFS dataset, in kibibytes (KiB). \n            For file systems using the Intelligent-Tiering storage class, valid values are 128, 256, 512, 1024, 2048, or 4096 KiB, with a default of 1024 KiB. \n            For all other file systems, valid values are 4, 8, 16, 32, 64, 128, 256, 512, or 1024 KiB, with a default of 128 KiB. \n            We recommend using the default setting for the majority of use cases. Generally, workloads that write in fixed small or large record sizes may benefit from setting a custom record size, like database workloads (small record size) or media streaming workloads (large record size).\n            For additional guidance on when to set a custom record size, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance.html#record-size-performance\">\n            ZFS Record size</a> in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Specifies the method used to compress the data on the volume. The compression\n            type is <code>NONE</code> by default.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Doesn't compress the data on the volume.\n                    <code>NONE</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ZSTD</code> - Compresses the data in the volume using the Zstandard\n                    (ZSTD) compression algorithm. ZSTD compression provides a higher level of \n                    data compression and higher read throughput performance than LZ4 compression.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Compresses the data in the volume using the LZ4\n                    compression algorithm. LZ4 compression provides a lower level of compression \n                    and higher write throughput performance than ZSTD compression.</p>\n            </li>\n         </ul>\n         <p>For more information about volume compression types and the performance of your Amazon FSx for OpenZFS file system,\n            see <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance.html#performance-tips-zfs\">\n                Tips for maximizing performance</a> File system and volume settings in the <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:copy_tags_to_snapshots, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToSnapshots', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the volume should be copied to snapshots.\n            This value defaults to <code>false</code>. If this value is set to <code>true</code>, and you do not specify any tags, all tags for the original volume are copied over to snapshots. \n            If this value is set to <code>true</code>, and you do specify one or more tags, only the specified tags for the original volume are copied over to snapshots. If you specify one or more tags when creating a new snapshot, no tags are copied over from the original volume, regardless of this value.\n        </p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:origin_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateOpenZFSOriginSnapshotConfiguration, location_name: 'OriginSnapshot', traits: {"smithy.api#documentation" => "<p>The configuration object that specifies the snapshot to use as the origin of the data\n            for the volume.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadOnly, location_name: 'ReadOnly', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether the volume is read-only.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:nfs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSNfsExports, location_name: 'NfsExports', traits: {"smithy.api#documentation" => "<p>The configuration object for mounting a Network File System (NFS) file system.</p>"}))
    CreateOpenZFSVolumeConfiguration.add_member(:user_and_group_quotas, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSUserAndGroupQuotas, location_name: 'UserAndGroupQuotas', traits: {"smithy.api#documentation" => "<p>Configures how much storage users and groups can use on the volume.</p>"}))
    CreateOpenZFSVolumeConfiguration.type = Types::CreateOpenZFSVolumeConfiguration
    CreateSnaplockConfiguration.add_member(:audit_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'AuditLogVolume', traits: {"smithy.api#documentation" => "<p>Enables or disables the audit log volume for an FSx for ONTAP SnapLock volume. The default \n            value is <code>false</code>. If you set <code>AuditLogVolume</code> to <code>true</code>, the SnapLock volume is \n            created as an audit log volume. The minimum retention period for an audit log volume is six months. </p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/how-snaplock-works.html#snaplock-audit-log-volume\">\n            SnapLock audit log volumes</a>. </p>"}))
    CreateSnaplockConfiguration.add_member(:autocommit_period, Smithy::Schema::Shapes::ShapeRef.new(shape: AutocommitPeriod, location_name: 'AutocommitPeriod', traits: {"smithy.api#documentation" => "<p>The configuration object for setting the autocommit period of files in an FSx for ONTAP SnapLock volume. </p>"}))
    CreateSnaplockConfiguration.add_member(:privileged_delete, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivilegedDelete, location_name: 'PrivilegedDelete', traits: {"smithy.api#documentation" => "<p>Enables, disables, or permanently disables privileged delete on an FSx for ONTAP SnapLock \n            Enterprise volume. Enabling privileged delete allows SnapLock administrators to delete WORM files even \n            if they have active retention periods. <code>PERMANENTLY_DISABLED</code> is a terminal state. \n            If privileged delete is permanently disabled on a SnapLock volume, you can't re-enable it. The default \n            value is <code>DISABLED</code>. </p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snaplock-enterprise.html#privileged-delete\">Privileged delete</a>. </p>"}))
    CreateSnaplockConfiguration.add_member(:retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: SnaplockRetentionPeriod, location_name: 'RetentionPeriod', traits: {"smithy.api#documentation" => "<p>Specifies the retention period of an FSx for ONTAP \n            SnapLock volume. </p>"}))
    CreateSnaplockConfiguration.add_member(:snaplock_type, Smithy::Schema::Shapes::ShapeRef.new(shape: SnaplockType, location_name: 'SnaplockType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the retention mode of an FSx for ONTAP SnapLock volume.  After it is set, it can't be changed. \n        You can choose one of the following retention modes: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>COMPLIANCE</code>: Files transitioned to write once, read many (WORM) on a Compliance volume can't be deleted \n                until their retention periods expire. This retention mode is used to address government or industry-specific mandates or to protect \n                against ransomware attacks. For more information, \n                see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snaplock-compliance.html\">SnapLock Compliance</a>. </p>\n            </li>\n            <li>\n               <p>\n                  <code>ENTERPRISE</code>: Files transitioned to WORM on an Enterprise volume can be deleted by authorized users \n            before their retention periods expire using privileged delete. This retention mode is used to advance an organization's data integrity \n            and internal compliance or to test retention settings before using SnapLock Compliance. For more information, see \n                <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snaplock-enterprise.html\">SnapLock Enterprise</a>. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateSnaplockConfiguration.add_member(:volume_append_mode_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'VolumeAppendModeEnabled', traits: {"smithy.api#documentation" => "<p>Enables or disables volume-append mode \n            on an FSx for ONTAP SnapLock volume. Volume-append mode allows you to \n            create WORM-appendable files and write data to them incrementally. The default value is <code>false</code>. </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/worm-state.html#worm-state-append\">Volume-append mode</a>. </p>"}))
    CreateSnaplockConfiguration.type = Types::CreateSnaplockConfiguration
