    CreateStorageVirtualMachineRequest.add_member(:active_directory_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateSvmActiveDirectoryConfiguration, location_name: 'ActiveDirectoryConfiguration', traits: {"smithy.api#documentation" => "<p>Describes the self-managed Microsoft Active Directory to which you want to join the SVM. \n      Joining an Active Directory provides user authentication and access control for SMB clients, \n      including Microsoft Windows and macOS clients accessing the file system.</p>"}))
