    CreateStorageVirtualMachineRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageVirtualMachineName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the SVM.</p>", "smithy.api#required" => {}}))
    CreateStorageVirtualMachineRequest.add_member(:svm_admin_password, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminPassword, location_name: 'SvmAdminPassword', traits: {"smithy.api#documentation" => "<p>The password to use when managing the SVM using the NetApp ONTAP CLI or REST API.\n            If you do not specify a password, you can still use the file system's\n            <code>fsxadmin</code> user to manage the SVM.</p>"}))
    CreateStorageVirtualMachineRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags'))
    CreateStorageVirtualMachineRequest.add_member(:root_volume_security_style, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageVirtualMachineRootVolumeSecurityStyle, location_name: 'RootVolumeSecurityStyle', traits: {"smithy.api#documentation" => "<p>The security style of the root volume of the SVM. Specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>UNIX</code> if the file system is managed by a UNIX\n                administrator, the majority of users are NFS clients, and an application\n                accessing the data uses a UNIX user as the service account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NTFS</code> if the file system is managed by a Microsoft Windows\n                administrator, the majority of users are SMB clients, and an application\n                accessing the data uses a Microsoft Windows user as the service account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MIXED</code> This is an advanced setting. For more information, see \n                <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/volume-security-style.html\">Volume security style</a>\n                in the Amazon FSx for NetApp ONTAP User Guide.</p>\n            </li>\n         </ul>\n         <p></p>"}))
