    CreateVolumeRequest.add_member(:ontap_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateOntapVolumeConfiguration, location_name: 'OntapConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the configuration to use when creating the ONTAP volume.</p>"}))
