    DataRepositoryTask.add_member(:paths, Smithy::Schema::Shapes::ShapeRef.new(shape: DataRepositoryTaskPaths, location_name: 'Paths', traits: {"smithy.api#documentation" => "<p>An array of paths that specify the data for the data repository task to process. \n            For example, in an EXPORT_TO_REPOSITORY task, the paths specify which data to export\n            to the linked data repository.</p>\n         <p>(Default) If <code>Paths</code> is not specified, Amazon FSx uses the file system root directory.</p>"}))
