    LustreFileSystemConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone. Here, <code>d</code> is the weekday number, from 1 through 7, beginning with Monday and\n            ending with Sunday.</p>"}))
    LustreFileSystemConfiguration.add_member(:data_repository_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DataRepositoryConfiguration, location_name: 'DataRepositoryConfiguration'))
    LustreFileSystemConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>The deployment type of the FSx for Lustre file system. \n            <i>Scratch deployment type</i> is designed for temporary storage\n            and shorter-term processing of data.</p>\n         <p>\n            <code>SCRATCH_1</code> and <code>SCRATCH_2</code> deployment types are best suited \n            for when you need temporary storage and shorter-term processing of data. The \n            <code>SCRATCH_2</code> deployment type provides in-transit encryption of data and higher burst \n            throughput capacity than <code>SCRATCH_1</code>.</p>\n         <p>The <code>PERSISTENT_1</code> and <code>PERSISTENT_2</code> deployment type is used\n            for longer-term storage and workloads and encryption of data in transit.\n                <code>PERSISTENT_2</code> offers higher <code>PerUnitStorageThroughput</code>\n            (up to 1000 MB/s/TiB) along with a lower minimum storage capacity requirement (600 GiB).\n            To learn more about FSx for Lustre deployment types, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/using-fsx-lustre.html\">Deployment and storage class options for\n                    FSx for Lustre file systems</a>.</p>\n         <p>The default is <code>SCRATCH_1</code>.</p>"}))
    LustreFileSystemConfiguration.add_member(:per_unit_storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: PerUnitStorageThroughput, location_name: 'PerUnitStorageThroughput', traits: {"smithy.api#documentation" => "<p>Per unit storage throughput represents the megabytes per second of read or write\n            throughput per 1 tebibyte of storage provisioned. File system throughput capacity is\n            equal to Storage capacity (TiB) * PerUnitStorageThroughput (MB/s/TiB). This option is\n            only valid for <code>PERSISTENT_1</code> and <code>PERSISTENT_2</code> deployment types. </p>\n         <p>Valid values:</p>\n         <ul>\n            <li>\n               <p>For <code>PERSISTENT_1</code> SSD storage: 50, 100, 200.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_1</code> HDD storage: 12, 40.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_2</code> SSD storage: 125, 250, 500, 1000.</p>\n            </li>\n         </ul>"}))
    LustreFileSystemConfiguration.add_member(:mount_name, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreFileSystemMountName, location_name: 'MountName', traits: {"smithy.api#documentation" => "<p>You use the <code>MountName</code> value when mounting the file system.</p>\n         <p>For the <code>SCRATCH_1</code> deployment type, this value is always \"<code>fsx</code>\". \n            For <code>SCRATCH_2</code>, <code>PERSISTENT_1</code>, and <code>PERSISTENT_2</code> deployment\n            types, this value is a string that is unique within an Amazon Web Services Region. \n        </p>"}))
    LustreFileSystemConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    LustreFileSystemConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    LustreFileSystemConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags on the file system are copied to backups.\n            If it's set to true, all tags on the file system are\n            copied to all automatic backups and any user-initiated backups where the user\n            doesn't specify any tags. If this value is true, and you specify one or more tags,\n            only the specified tags are copied to backups. If you specify one or more tags when \n            creating a user-initiated backup, no tags are copied from the file system, \n            regardless of this value. (Default = false)</p>"}))
    LustreFileSystemConfiguration.add_member(:drive_cache_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DriveCacheType, location_name: 'DriveCacheType', traits: {"smithy.api#documentation" => "<p>The type of drive cache used by <code>PERSISTENT_1</code> file systems that are provisioned with\n            HDD storage devices. This parameter is required when <code>StorageType</code> is HDD. When set to\n            <code>READ</code> the file system has an SSD storage cache that is sized to 20% of the file system's\n            storage capacity. This improves the performance for frequently accessed files by caching up to 20%\n            of the total storage capacity.</p>\n         <p>This parameter is required when <code>StorageType</code> is set to HDD.</p>"}))
    LustreFileSystemConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>The data compression configuration for the file system. <code>DataCompressionType</code>\n            can have the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Data compression is turned off for\n                the file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Data compression is turned on with the LZ4\n                algorithm.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/data-compression.html\">Lustre data compression</a>.</p>"}))
    LustreFileSystemConfiguration.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreLogConfiguration, location_name: 'LogConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre logging configuration. Lustre logging writes the enabled log\n            events for your file system to Amazon CloudWatch Logs.</p>"}))
    LustreFileSystemConfiguration.add_member(:root_squash_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreRootSquashConfiguration, location_name: 'RootSquashConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre root squash configuration for an Amazon FSx for Lustre\n            file system. When enabled, root squash restricts root-level access from clients that\n            try to access your file system as a root user.</p>"}))
    LustreFileSystemConfiguration.add_member(:metadata_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemLustreMetadataConfiguration, location_name: 'MetadataConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre metadata performance configuration for an Amazon FSx for Lustre file system\n            using a <code>PERSISTENT_2</code> deployment type.</p>"}))
    LustreFileSystemConfiguration.add_member(:efa_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'EfaEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether Elastic Fabric Adapter (EFA) and GPUDirect Storage (GDS)\n            support is enabled for the Amazon FSx for Lustre file system.</p>"}))
    LustreFileSystemConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityMbps, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>The throughput of an Amazon FSx for Lustre file system using the Intelligent-Tiering\n            storage class, measured in megabytes per second (MBps).</p>"}))
    LustreFileSystemConfiguration.add_member(:data_read_cache_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreReadCacheConfiguration, location_name: 'DataReadCacheConfiguration', traits: {"smithy.api#documentation" => "<p>Required when <code>StorageType</code> is set to <code>INTELLIGENT_TIERING</code>.\n            Specifies the optional provisioned SSD read cache.</p>"}))
    LustreFileSystemConfiguration.type = Types::LustreFileSystemConfiguration
    LustreLogConfiguration.add_member(:level, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreAccessAuditLogLevel, location_name: 'Level', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The data repository events that are logged by Amazon FSx.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>WARN_ONLY</code> - only warning events are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR_ONLY</code> - only error events are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>WARN_ERROR</code> - both warning events and error events\n                    are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - logging of data repository events\n                    is turned off.</p>\n            </li>\n         </ul>\n         <p>Note that Amazon File Cache uses a default setting of <code>WARN_ERROR</code>,\n            which can't be changed.</p>", "smithy.api#required" => {}}))
    LustreLogConfiguration.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneralARN, location_name: 'Destination', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) that specifies the destination of the logs.\n            The destination can be any Amazon CloudWatch Logs log group ARN. The destination\n            ARN must be in the same Amazon Web Services partition, Amazon Web Services Region,\n            and Amazon Web Services account as your Amazon FSx file system.</p>"}))
    LustreLogConfiguration.type = Types::LustreLogConfiguration
    LustreLogCreateConfiguration.add_member(:level, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreAccessAuditLogLevel, location_name: 'Level', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets which data repository events are logged by Amazon FSx.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>WARN_ONLY</code> - only warning events are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR_ONLY</code> - only error events are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>WARN_ERROR</code> - both warning events and error events\n                    are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - logging of data repository events\n                    is turned off.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    LustreLogCreateConfiguration.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneralARN, location_name: 'Destination', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) that specifies the destination of the logs.</p>\n         <p>The destination can be any Amazon CloudWatch Logs log group ARN, with the following\n            requirements:</p>\n         <ul>\n            <li>\n               <p>The destination ARN that you provide must be in the same Amazon Web Services partition,\n                    Amazon Web Services Region, and Amazon Web Services account as your Amazon FSx file system.</p>\n            </li>\n            <li>\n               <p>The name of the Amazon CloudWatch Logs log group must begin with\n                    the <code>/aws/fsx</code> prefix.</p>\n            </li>\n            <li>\n               <p>If you do not provide a destination, Amazon FSx will create and use a\n                    log stream in the CloudWatch Logs <code>/aws/fsx/lustre</code> log group\n                    (for Amazon FSx for Lustre) or <code>/aws/fsx/filecache</code>\n                    (for Amazon File Cache).</p>\n            </li>\n            <li>\n               <p>If <code>Destination</code> is provided and the resource does not\n                    exist, the request will fail with a <code>BadRequest</code> error.</p>\n            </li>\n            <li>\n               <p>If <code>Level</code> is set to <code>DISABLED</code>, you cannot specify\n                    a destination in <code>Destination</code>.</p>\n            </li>\n         </ul>"}))
    LustreLogCreateConfiguration.type = Types::LustreLogCreateConfiguration
    LustreNoSquashNids.member = Smithy::Schema::Shapes::ShapeRef.new(shape: LustreNoSquashNid)
    LustreReadCacheConfiguration.add_member(:sizing_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreReadCacheSizingMode, location_name: 'SizingMode', traits: {"smithy.api#documentation" => "<p>\n            Specifies how the provisioned SSD read cache is sized, as follows:\n        </p>\n         <ul>\n            <li>\n               <p>Set to <code>NO_CACHE</code> if you do not want to use an SSD read cache with your Intelligent-Tiering file system.</p>\n            </li>\n            <li>\n               <p>Set to <code>USER_PROVISIONED</code> to specify the exact size of your SSD read cache.</p>\n            </li>\n            <li>\n               <p>Set to <code>PROPORTIONAL_TO_THROUGHPUT_CAPACITY</code> to have your SSD read cache automatically sized based on your throughput capacity.</p>\n            </li>\n         </ul>"}))
    LustreReadCacheConfiguration.add_member(:size_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacity, location_name: 'SizeGiB', traits: {"smithy.api#documentation" => "<p>\n            Required if <code>SizingMode</code> is set to <code>USER_PROVISIONED</code>.\n            Specifies the size of the file system's SSD read cache, in gibibytes (GiB).\n        </p>\n         <p>The SSD read cache size is distributed across provisioned file servers in\n            your file system. Intelligent-Tiering file systems support a minimum of 32 GiB\n            and maximum of 131072 GiB for SSD read cache size for every 4,000 MB/s of throughput\n            capacity provisioned.</p>"}))
    LustreReadCacheConfiguration.type = Types::LustreReadCacheConfiguration
    LustreReadCacheSizingMode.add_member(:no_cache, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NO_CACHE', traits: {"smithy.api#enumValue" => "NO_CACHE"}))
    LustreReadCacheSizingMode.add_member(:user_provisioned, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'USER_PROVISIONED', traits: {"smithy.api#enumValue" => "USER_PROVISIONED"}))
    LustreReadCacheSizingMode.add_member(:proportional_to_throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROPORTIONAL_TO_THROUGHPUT_CAPACITY', traits: {"smithy.api#enumValue" => "PROPORTIONAL_TO_THROUGHPUT_CAPACITY"}))
    LustreRootSquashConfiguration.add_member(:root_squash, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreRootSquash, location_name: 'RootSquash', traits: {"smithy.api#documentation" => "<p>You enable root squash by setting a user ID (UID) and group ID (GID) for the file\n            system in the format <code>UID:GID</code> (for example, <code>365534:65534</code>).\n            The UID and GID values can range from <code>0</code> to <code>4294967294</code>:</p>\n         <ul>\n            <li>\n               <p>A non-zero value for UID and GID enables root squash. The UID and GID\n                values can be different, but each must be a non-zero value.</p>\n            </li>\n            <li>\n               <p>A value of <code>0</code> (zero) for UID and GID indicates root,\n                and therefore disables root squash.</p>\n            </li>\n         </ul>\n         <p>When root squash is enabled, the user ID and group ID of a root user accessing\n            the file system are re-mapped to the UID and GID you provide.</p>"}))
    LustreRootSquashConfiguration.add_member(:no_squash_nids, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreNoSquashNids, location_name: 'NoSquashNids', traits: {"smithy.api#documentation" => "<p>When root squash is enabled, you can optionally specify an array of NIDs of clients\n            for which root squash does not apply. A client NID is a Lustre Network Identifier used\n            to uniquely identify a client. You can specify the NID as either a single address or a\n            range of addresses:</p>\n         <ul>\n            <li>\n               <p>A single address is described in standard Lustre NID format by specifying\n                the client’s IP address followed by the Lustre network ID (for example,\n                <code>10.0.1.6@tcp</code>).</p>\n            </li>\n            <li>\n               <p>An address range is described using a dash to separate the range (for example,\n                <code>10.0.[2-10].[1-255]@tcp</code>).</p>\n            </li>\n         </ul>"}))
    LustreRootSquashConfiguration.type = Types::LustreRootSquashConfiguration
