    OntapFileSystemConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OntapDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>Specifies the FSx for ONTAP file system deployment type in use in the file\n            system. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>MULTI_AZ_1</code> - A high availability file system configured\n                    for Multi-AZ redundancy to tolerate temporary Availability Zone (AZ)\n                    unavailability. This is a first-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MULTI_AZ_2</code> - A high availability file system configured for Multi-AZ redundancy to tolerate \n                temporary AZ unavailability. This is a second-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_1</code> - A file system configured for Single-AZ\n                    redundancy. This is a first-generation FSx for ONTAP file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_2</code> - A file system configured with multiple high-availability (HA) pairs for Single-AZ redundancy. \n                This is a second-generation FSx for ONTAP file system.</p>\n            </li>\n         </ul>\n         <p>For information about the use cases for Multi-AZ and Single-AZ deployments, refer to\n                <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/high-availability-multiAZ.html\">Choosing Multi-AZ or\n                Single-AZ file system deployment</a>. </p>"}))
    OntapFileSystemConfiguration.add_member(:endpoint_ip_address_range, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressRange, location_name: 'EndpointIpAddressRange', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the IP address range in which the endpoints to access your\n            file system will be created. By default in the Amazon FSx  API, Amazon FSx\n            selects an unused IP address range for you from the 198.19.* range. By default in the \n            Amazon FSx  console, Amazon FSx  chooses the last 64 IP addresses from\n            the VPC’s primary CIDR range to use as the endpoint IP address range for the file system.\n            You can have overlapping endpoint IP addresses for file systems deployed in the\n            same VPC/route tables.</p>"}))
    OntapFileSystemConfiguration.add_member(:endpoints, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemEndpoints, location_name: 'Endpoints', traits: {"smithy.api#documentation" => "<p>The <code>Management</code> and <code>Intercluster</code> endpoints\n            that are used to access data or to manage the file system using the\n            NetApp ONTAP CLI, REST API, or NetApp SnapMirror.</p>"}))
    OntapFileSystemConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS configuration for the ONTAP file system, specifying\n            the number of provisioned IOPS and the provision mode.</p>"}))
    OntapFileSystemConfiguration.add_member(:preferred_subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'PreferredSubnetId'))
    OntapFileSystemConfiguration.add_member(:route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'RouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) The VPC route tables in which your file system's endpoints are\n            created.</p>"}))
    OntapFileSystemConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity'))
    OntapFileSystemConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    OntapFileSystemConfiguration.add_member(:fsx_admin_password, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminPassword, location_name: 'FsxAdminPassword', traits: {"smithy.api#documentation" => "<p>You can use the <code>fsxadmin</code> user account to access the NetApp ONTAP CLI and \n        REST API. The password value is always redacted in the response.</p>"}))
    OntapFileSystemConfiguration.add_member(:ha_pairs, Smithy::Schema::Shapes::ShapeRef.new(shape: HAPairs, location_name: 'HAPairs', traits: {"smithy.api#documentation" => "<p>Specifies how many high-availability (HA) file server pairs the file system will have. The default value is 1. The value of this property affects the values of <code>StorageCapacity</code>, \n            <code>Iops</code>, and <code>ThroughputCapacity</code>. For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/HA-pairs.html\">High-availability (HA) pairs</a> in the FSx for ONTAP user guide.</p>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>HAPairs</code> is less than 1 or greater than 12.</p>\n            </li>\n            <li>\n               <p>The value of <code>HAPairs</code> is greater than 1 and the value of <code>DeploymentType</code> is <code>SINGLE_AZ_1</code>, <code>MULTI_AZ_1</code>, or <code>MULTI_AZ_2</code>.</p>\n            </li>\n         </ul>"}))
    OntapFileSystemConfiguration.add_member(:throughput_capacity_per_ha_pair, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityPerHAPair, location_name: 'ThroughputCapacityPerHAPair', traits: {"smithy.api#documentation" => "<p>Use to choose the throughput capacity per HA pair. When the value of <code>HAPairs</code> is equal to 1, the value of <code>ThroughputCapacityPerHAPair</code> is the total throughput for the file system.</p>\n         <p>This field and <code>ThroughputCapacity</code> cannot be defined in the same API call, but one is required.</p>\n         <p>This field and <code>ThroughputCapacity</code> are the same for file systems with one HA pair.</p>\n         <ul>\n            <li>\n               <p>For <code>SINGLE_AZ_1</code> and <code>MULTI_AZ_1</code> file systems, valid values are 128, 256, 512, 1024, 2048, or 4096 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>SINGLE_AZ_2</code>, valid values are 1536, 3072, or 6144 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>MULTI_AZ_2</code>, valid values are 384, 768, 1536, 3072, or 6144 MBps.</p>\n            </li>\n         </ul>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> and <code>ThroughputCapacityPerHAPair</code> are not the same value.</p>\n            </li>\n            <li>\n               <p>The value of deployment type is <code>SINGLE_AZ_2</code> and <code>ThroughputCapacity</code> / <code>ThroughputCapacityPerHAPair</code> is not a valid HA pair (a value between 1 and 12).</p>\n            </li>\n            <li>\n               <p>The value of <code>ThroughputCapacityPerHAPair</code> is not a valid value.</p>\n            </li>\n         </ul>"}))
    OntapFileSystemConfiguration.type = Types::OntapFileSystemConfiguration
    OntapVolumeConfiguration.add_member(:flex_cache_endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FlexCacheEndpointType, location_name: 'FlexCacheEndpointType', traits: {"smithy.api#documentation" => "<p>Specifies the FlexCache endpoint type of the volume.\n            Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> specifies that the volume doesn't have a FlexCache configuration.\n                <code>NONE</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ORIGIN</code> specifies that the volume is the origin volume for a FlexCache volume.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CACHE</code> specifies that the volume is a FlexCache volume.</p>\n            </li>\n         </ul>"}))
    OntapVolumeConfiguration.add_member(:junction_path, Smithy::Schema::Shapes::ShapeRef.new(shape: JunctionPath, location_name: 'JunctionPath', traits: {"smithy.api#documentation" => "<p>Specifies the directory that network-attached storage (NAS) clients use to mount the\n            volume, along with the storage virtual machine (SVM) Domain Name System (DNS) name or IP\n            address. You can create a <code>JunctionPath</code> directly below a parent volume\n            junction or on a directory within a volume. A <code>JunctionPath</code> for a volume\n            named <code>vol3</code> might be <code>/vol1/vol2/vol3</code>, or\n                <code>/vol1/dir2/vol3</code>, or even <code>/dir1/dir2/vol3</code>.</p>"}))
    OntapVolumeConfiguration.add_member(:security_style, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityStyle, location_name: 'SecurityStyle', traits: {"smithy.api#documentation" => "<p>The security style for the volume, which can be <code>UNIX</code>, <code>NTFS</code>,\n            or\n                <code>MIXED</code>.</p>"}))
    OntapVolumeConfiguration.add_member(:size_in_megabytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacity, location_name: 'SizeInMegabytes', traits: {"smithy.api#documentation" => "<p>The configured size of the volume, in megabytes (MBs).</p>"}))
    OntapVolumeConfiguration.add_member(:storage_efficiency_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'StorageEfficiencyEnabled', traits: {"smithy.api#documentation" => "<p>The volume's storage efficiency setting.</p>"}))
    OntapVolumeConfiguration.add_member(:storage_virtual_machine_id, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageVirtualMachineId, location_name: 'StorageVirtualMachineId', traits: {"smithy.api#documentation" => "<p>The ID of the volume's storage virtual machine.</p>"}))
    OntapVolumeConfiguration.add_member(:storage_virtual_machine_root, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'StorageVirtualMachineRoot', traits: {"smithy.api#documentation" => "<p>A Boolean flag indicating whether this volume is the root volume for its storage\n            virtual machine (SVM). Only one volume on an SVM can be the root volume. This value\n            defaults to <code>false</code>. If this value is <code>true</code>, then this is the SVM\n            root volume.</p>\n         <p>This flag is useful when you're deleting an SVM, because you must first delete all\n            non-root volumes. This flag, when set to <code>false</code>, helps you identify which\n            volumes to delete before you can delete the SVM.</p>"}))
    OntapVolumeConfiguration.add_member(:tiering_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: TieringPolicy, location_name: 'TieringPolicy', traits: {"smithy.api#documentation" => "<p>The volume's <code>TieringPolicy</code> setting.</p>"}))
    OntapVolumeConfiguration.add_member(:uuid, Smithy::Schema::Shapes::ShapeRef.new(shape: UUID, location_name: 'UUID', traits: {"smithy.api#documentation" => "<p>The volume's universally unique identifier (UUID).</p>"}))
    OntapVolumeConfiguration.add_member(:ontap_volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OntapVolumeType, location_name: 'OntapVolumeType', traits: {"smithy.api#documentation" => "<p>Specifies the type of volume. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>RW</code> specifies a read/write volume. <code>RW</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DP</code> specifies a data-protection volume. You can protect data by replicating it to\n                    data-protection mirror copies. If a disaster occurs, you can use these\n                    data-protection mirror copies to recover data.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LS</code> specifies a load-sharing mirror volume. A load-sharing mirror reduces the\n                    network traffic to a FlexVol volume by providing additional read-only access to\n                    clients.</p>\n            </li>\n         </ul>"}))
    OntapVolumeConfiguration.add_member(:snapshot_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotPolicy, location_name: 'SnapshotPolicy', traits: {"smithy.api#documentation" => "<p>Specifies the snapshot policy for the volume. There are three built-in snapshot policies:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code>: This is the default policy. A maximum of six hourly snapshots taken five minutes past \n                the hour. A maximum of two daily snapshots taken Monday through Saturday at 10 minutes after\n                midnight. A maximum of two weekly snapshots taken every Sunday at 15 minutes after midnight.</p>\n            </li>\n            <li>\n               <p>\n                  <code>default-1weekly</code>: This policy is the same as the <code>default</code> policy except \n                that it only retains one snapshot from the weekly schedule.</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code>: This policy does not take any snapshots. This policy can be assigned to volumes to \n                prevent automatic snapshots from being taken.</p>\n            </li>\n         </ul>\n         <p>You can also provide the name of a custom policy that you created with the ONTAP CLI or REST API.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snapshots-ontap.html#snapshot-policies\">Snapshot policies</a> \n            in the Amazon FSx for NetApp ONTAP User Guide.</p>"}))
    OntapVolumeConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags for the volume should be copied to backups. This value defaults to\n            false. If it's set to true, all tags for the volume are copied to all automatic and user-initiated backups\n            where the user doesn't specify tags. If this value is true, and you specify one or more tags, only the\n            specified tags are copied to backups. If you specify one or more tags when creating a user-initiated\n            backup, no tags are copied from the volume, regardless of this value.</p>"}))
    OntapVolumeConfiguration.add_member(:snaplock_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SnaplockConfiguration, location_name: 'SnaplockConfiguration', traits: {"smithy.api#documentation" => "<p>The SnapLock configuration object for an FSx for ONTAP SnapLock volume. </p>"}))
    OntapVolumeConfiguration.add_member(:volume_style, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeStyle, location_name: 'VolumeStyle', traits: {"smithy.api#documentation" => "<p>Use to specify the style of an ONTAP volume. For more information about FlexVols and FlexGroups, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/volume-types.html\">Volume types</a> in Amazon FSx for NetApp ONTAP User Guide.</p>"}))
    OntapVolumeConfiguration.add_member(:aggregate_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AggregateConfiguration, location_name: 'AggregateConfiguration', traits: {"smithy.api#documentation" => "<p>This structure specifies configuration options for a volume’s storage aggregate or aggregates.</p>"}))
    OntapVolumeConfiguration.add_member(:size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacityBytes, location_name: 'SizeInBytes', traits: {"smithy.api#documentation" => "<p>The configured size of the volume, in bytes.</p>"}))
    OntapVolumeConfiguration.type = Types::OntapVolumeConfiguration
    OntapVolumeType.add_member(:rw, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'RW', traits: {"smithy.api#enumValue" => "RW"}))
    OntapVolumeType.add_member(:dp, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DP', traits: {"smithy.api#enumValue" => "DP"}))
    OntapVolumeType.add_member(:ls, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LS', traits: {"smithy.api#enumValue" => "LS"}))
    OpenZFSClientConfiguration.add_member(:clients, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSClients, location_name: 'Clients', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A value that specifies who can mount the file system. You can provide a wildcard\n            character (<code>*</code>), an IP address (<code>0.0.0.0</code>), or a CIDR address\n                (<code>192.0.2.0/24</code>). By default, Amazon FSx uses the wildcard\n            character when specifying the client. </p>", "smithy.api#required" => {}}))
    OpenZFSClientConfiguration.add_member(:options, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSNfsExportOptions, location_name: 'Options', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The options to use when mounting the file system. For a list of options that you can\n            use with Network File System (NFS), see the <a href=\"https://linux.die.net/man/5/exports\">exports(5) - Linux man page</a>. When\n            choosing your options, consider the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>crossmnt</code> is used by default. If you don't specify\n                    <code>crossmnt</code> when changing the client configuration, you won't be\n                    able to see or access snapshots in your file system's snapshot directory.</p>\n            </li>\n            <li>\n               <p>\n                  <code>sync</code> is used by default. If you instead specify\n                        <code>async</code>, the system acknowledges writes before writing to disk.\n                    If the system crashes before the writes are finished, you lose the unwritten\n                    data. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    OpenZFSClientConfiguration.type = Types::OpenZFSClientConfiguration
    OpenZFSClientConfigurations.member = Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSClientConfiguration)
    OpenZFSCopyStrategy.add_member(:clone, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CLONE', traits: {"smithy.api#enumValue" => "CLONE"}))
    OpenZFSCopyStrategy.add_member(:full_copy, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FULL_COPY', traits: {"smithy.api#enumValue" => "FULL_COPY"}))
    OpenZFSCopyStrategy.add_member(:incremental_copy, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INCREMENTAL_COPY', traits: {"smithy.api#enumValue" => "INCREMENTAL_COPY"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:record_size_ki_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerRecordSizeKiB, location_name: 'RecordSizeKiB', traits: {"smithy.api#documentation" => "<p>Specifies the record size of an OpenZFS root volume, in kibibytes (KiB). Valid values are 4, 8,\n        16, 32, 64, 128, 256, 512, or 1024 KiB. The default is 128 KiB. Most workloads should use the \n        default record size. Database workflows can benefit from a smaller record size, while streaming \n        workflows can benefit from a larger record size. For additional guidance on setting a custom record \n        size, see <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance.html#performance-tips-zfs\">\n        Tips for maximizing performance</a> in the\n        <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Specifies the method used to compress the data on the volume. The compression\n            type is <code>NONE</code> by default.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Doesn't compress the data on the volume.\n                    <code>NONE</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ZSTD</code> - Compresses the data in the volume using the Zstandard\n                    (ZSTD) compression algorithm. Compared to LZ4, Z-Standard provides a better\n                    compression ratio to minimize on-disk storage utilization.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Compresses the data in the volume using the LZ4\n                    compression algorithm. Compared to Z-Standard, LZ4 is less compute-intensive\n                    and delivers higher write throughput speeds.</p>\n            </li>\n         </ul>"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:nfs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSNfsExports, location_name: 'NfsExports', traits: {"smithy.api#documentation" => "<p>The configuration object for mounting a file system.</p>"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:user_and_group_quotas, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSUserAndGroupQuotas, location_name: 'UserAndGroupQuotas', traits: {"smithy.api#documentation" => "<p>An object specifying how much storage users or groups can use on the volume.</p>"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:copy_tags_to_snapshots, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToSnapshots', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the volume should be copied to snapshots\n            of the volume. This value defaults to <code>false</code>. If it's set to <code>true</code>,\n            all tags for the volume are copied to snapshots where the user doesn't specify tags. If this\n            value is <code>true</code> and you specify one or more tags, only the specified tags are\n            copied to snapshots. If you specify one or more tags when creating the snapshot, no tags\n            are copied from the volume, regardless of this value. </p>"}))
    OpenZFSCreateRootVolumeConfiguration.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadOnly, location_name: 'ReadOnly', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether the volume is read-only. Setting this value to\n                <code>true</code> can be useful after you have completed changes to a volume and no\n            longer want changes to occur. </p>"}))
    OpenZFSCreateRootVolumeConfiguration.type = Types::OpenZFSCreateRootVolumeConfiguration
    OpenZFSDataCompressionType.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NONE', traits: {"smithy.api#enumValue" => "NONE"}))
    OpenZFSDataCompressionType.add_member(:zstd, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ZSTD', traits: {"smithy.api#enumValue" => "ZSTD"}))
    OpenZFSDataCompressionType.add_member(:lz4, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LZ4', traits: {"smithy.api#enumValue" => "LZ4"}))
    OpenZFSDeploymentType.add_member(:single_az_1, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SINGLE_AZ_1', traits: {"smithy.api#enumValue" => "SINGLE_AZ_1"}))
    OpenZFSDeploymentType.add_member(:single_az_2, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SINGLE_AZ_2', traits: {"smithy.api#enumValue" => "SINGLE_AZ_2"}))
    OpenZFSDeploymentType.add_member(:single_az_ha_1, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SINGLE_AZ_HA_1', traits: {"smithy.api#enumValue" => "SINGLE_AZ_HA_1"}))
    OpenZFSDeploymentType.add_member(:single_az_ha_2, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SINGLE_AZ_HA_2', traits: {"smithy.api#enumValue" => "SINGLE_AZ_HA_2"}))
    OpenZFSDeploymentType.add_member(:multi_az_1, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MULTI_AZ_1', traits: {"smithy.api#enumValue" => "MULTI_AZ_1"}))
    OpenZFSFileSystemConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    OpenZFSFileSystemConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags on the file system should be copied to\n            backups.\n            If it's set to <code>true</code>, all tags on the file system are copied to all\n            automatic backups and any user-initiated backups where the user doesn't specify any\n            tags. If this value is <code>true</code> and you specify one or more tags, only the\n            specified tags are copied to backups. If you specify one or more tags when creating a\n            user-initiated backup, no tags are copied from the file system, regardless of this\n            value. </p>"}))
    OpenZFSFileSystemConfiguration.add_member(:copy_tags_to_volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToVolumes', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the volume should be copied to snapshots.\n            This value defaults to <code>false</code>. If it's set to <code>true</code>, all tags\n            for the volume are copied to snapshots where the user doesn't specify tags. If this\n            value is <code>true</code> and you specify one or more tags, only the specified tags are\n            copied to snapshots. If you specify one or more tags when creating the snapshot, no tags\n            are copied from the volume, regardless of this value. </p>"}))
    OpenZFSFileSystemConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    OpenZFSFileSystemConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>Specifies the file-system deployment type. Amazon FSx for OpenZFS supports\u2028 <code>MULTI_AZ_1</code>, <code>SINGLE_AZ_HA_2</code>, <code>SINGLE_AZ_HA_1</code>, <code>SINGLE_AZ_2</code>, and <code>SINGLE_AZ_1</code>.</p>"}))
    OpenZFSFileSystemConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>The throughput of an Amazon FSx file system, measured in megabytes per second (MBps).</p>"}))
