    OpenZFSVolumeConfiguration.add_member(:record_size_ki_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerRecordSizeKiB, location_name: 'RecordSizeKiB', traits: {"smithy.api#documentation" => "<p>The record size of an OpenZFS volume, in kibibytes (KiB). Valid values are 4, 8,\n            16, 32, 64, 128, 256, 512, or 1024 KiB. The default is 128 KiB.\n            Most workloads should use the default record size. For guidance on when\n            to set a custom record size, see the\n            <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    OpenZFSVolumeConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Specifies the method used to compress the data on the volume. The compression\n            type is <code>NONE</code> by default.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Doesn't compress the data on the volume.\n                    <code>NONE</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ZSTD</code> - Compresses the data in the volume using the Zstandard\n                    (ZSTD) compression algorithm. Compared to LZ4, Z-Standard provides a better\n                    compression ratio to minimize on-disk storage utilization.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Compresses the data in the volume using the LZ4\n                    compression algorithm. Compared to Z-Standard, LZ4 is less compute-intensive\n                    and delivers higher write throughput speeds.</p>\n            </li>\n         </ul>"}))
    OpenZFSVolumeConfiguration.add_member(:copy_tags_to_snapshots, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToSnapshots', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the volume should be copied to snapshots.\n            This value defaults to <code>false</code>. If it's set to <code>true</code>, all tags\n            for the volume are copied to snapshots where the user doesn't specify tags. If this\n            value is <code>true</code> and you specify one or more tags, only the specified tags are\n            copied to snapshots. If you specify one or more tags when creating the snapshot, no tags\n            are copied from the volume, regardless of this value.</p>"}))
    OpenZFSVolumeConfiguration.add_member(:origin_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSOriginSnapshotConfiguration, location_name: 'OriginSnapshot', traits: {"smithy.api#documentation" => "<p>The configuration object that specifies the snapshot to use as the origin of the data\n            for the volume.</p>"}))
