    SelfManagedActiveDirectoryConfiguration.add_member(:dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: DnsIps, location_name: 'DnsIps', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of up to three IP addresses of DNS servers or domain controllers in the\n            self-managed AD directory. </p>", "smithy.api#required" => {}}))
