    UntagResourceRequest.add_member(:tag_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: TagKeys, location_name: 'TagKeys', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of keys of tags on the resource to untag. In case the tag key doesn't exist,\n            the call will still succeed to be idempotent.</p>", "smithy.api#required" => {}}))
