    UpdateDataRepositoryAssociationRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#idempotencyToken" => {}}))
    UpdateDataRepositoryAssociationRequest.add_member(:imported_file_chunk_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Megabytes, location_name: 'ImportedFileChunkSize', traits: {"smithy.api#documentation" => "<p>For files imported from a data repository, this value determines the stripe count and\n            maximum amount of data per file (in MiB) stored on a single physical disk. The maximum\n            number of disks that a single file can be striped across is limited by the total number\n            of disks that make up the file system.</p>\n         <p>The default chunk size is 1,024 MiB (1 GiB) and can go as high as 512,000 MiB (500\n            GiB). Amazon S3 objects have a maximum size of 5 TB.</p>"}))
    UpdateDataRepositoryAssociationRequest.add_member(:s3, Smithy::Schema::Shapes::ShapeRef.new(shape: S3DataRepositoryConfiguration, location_name: 'S3', traits: {"smithy.api#documentation" => "<p>The configuration for an Amazon S3 data repository linked to an\n            Amazon FSx Lustre file system with a data repository association.\n            The configuration defines which file events (new, changed, or\n            deleted files or directories) are automatically imported from\n            the linked data repository to the file system or automatically\n            exported from the file system to the data repository.</p>"}))
    UpdateDataRepositoryAssociationRequest.type = Types::UpdateDataRepositoryAssociationRequest
    UpdateDataRepositoryAssociationResponse.add_member(:association, Smithy::Schema::Shapes::ShapeRef.new(shape: DataRepositoryAssociation, location_name: 'Association', traits: {"smithy.api#documentation" => "<p>The response object returned after the data repository association is updated.</p>"}))
    UpdateDataRepositoryAssociationResponse.type = Types::UpdateDataRepositoryAssociationResponse
    UpdateFileCacheLustreConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    UpdateFileCacheLustreConfiguration.type = Types::UpdateFileCacheLustreConfiguration
    UpdateFileCacheRequest.add_member(:file_cache_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FileCacheId, location_name: 'FileCacheId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the cache that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateFileCacheRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#idempotencyToken" => {}}))
    UpdateFileCacheRequest.add_member(:lustre_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateFileCacheLustreConfiguration, location_name: 'LustreConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration updates for an Amazon File Cache resource.</p>"}))
    UpdateFileCacheRequest.type = Types::UpdateFileCacheRequest
