    UpdateFileCacheResponse.type = Types::UpdateFileCacheResponse
    UpdateFileSystemLustreConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>(Optional) The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone. d is the weekday number, from 1 through 7, beginning with Monday and ending with Sunday.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    UpdateFileSystemLustreConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays', traits: {"smithy.api#documentation" => "<p>The number of days to retain automatic backups. Setting this property to\n            <code>0</code> disables automatic backups. You can retain automatic backups for a\n            maximum of 90 days. The default is <code>0</code>.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:auto_import_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoImportPolicyType, location_name: 'AutoImportPolicy', traits: {"smithy.api#documentation" => "<p> (Optional) When you create your file system, your existing S3 objects appear as file and directory listings. \n            Use this property to choose how Amazon FSx keeps your file and directory listing up to date \n            as you add or modify objects in your linked S3 bucket. <code>AutoImportPolicy</code> can\n            have the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - (Default) AutoImport is off. Amazon FSx only updates \n                file and directory listings from the linked S3 bucket \n                when the file system is created. FSx does not update the file and directory \n                listing for any new or changed objects after choosing this option.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW</code> - AutoImport is on. Amazon FSx automatically imports\n                directory listings of any new objects added to the linked S3 bucket that \n                do not currently exist in the FSx file system. </p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_CHANGED</code> - AutoImport is on. Amazon FSx automatically imports \n                file and directory listings of any new objects added to the S3 bucket and any \n                existing objects that are changed in the S3 bucket after you choose this option.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_CHANGED_DELETED</code> - AutoImport is on. Amazon FSx automatically\n                imports file and directory listings of any new objects added to the S3 bucket, any \n                existing objects that are changed in the S3 bucket, and any objects that were deleted\n                in the S3 bucket.</p>\n            </li>\n         </ul>\n         <p>This parameter is not supported for file systems with a data repository association.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: DataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Sets the data compression configuration for the file system. <code>DataCompressionType</code>\n            can have the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Data compression is turned off for\n                the file system.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Data compression is turned on with the LZ4\n                algorithm.</p>\n            </li>\n         </ul>\n         <p>If you don't use <code>DataCompressionType</code>, the file system retains\n            its current data compression configuration.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/data-compression.html\">Lustre data compression</a>.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreLogCreateConfiguration, location_name: 'LogConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre logging configuration used when updating an Amazon FSx for Lustre\n            file system. When logging is enabled, Lustre logs error and warning events for\n            data repositories associated with your file system to Amazon CloudWatch Logs.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:root_squash_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreRootSquashConfiguration, location_name: 'RootSquashConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre root squash configuration used when updating an Amazon FSx for Lustre\n            file system. When enabled, root squash restricts root-level access from clients that\n            try to access your file system as a root user.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:per_unit_storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: PerUnitStorageThroughput, location_name: 'PerUnitStorageThroughput', traits: {"smithy.api#documentation" => "<p>The throughput of an Amazon FSx for Lustre Persistent SSD-based file system,\n            measured in megabytes per second per tebibyte (MB/s/TiB). You can increase or decrease\n            your file system's throughput. Valid values depend on the deployment type of the file\n            system, as follows:</p>\n         <ul>\n            <li>\n               <p>For <code>PERSISTENT_1</code> SSD-based deployment types, valid values\n                are 50, 100, and 200 MB/s/TiB.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT_2</code> SSD-based deployment types, valid values\n                are 125, 250, 500, and 1000 MB/s/TiB.</p>\n            </li>\n         </ul>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/managing-throughput-capacity.html\">\n                Managing throughput capacity</a>.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:metadata_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateFileSystemLustreMetadataConfiguration, location_name: 'MetadataConfiguration', traits: {"smithy.api#documentation" => "<p>The Lustre metadata performance configuration for an Amazon FSx for Lustre\n            file system using a <code>PERSISTENT_2</code> deployment type. When this configuration\n            is enabled, the file system supports increasing metadata performance.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityMbps, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>The throughput of an Amazon FSx for Lustre file system using an Intelligent-Tiering\n            storage class, measured in megabytes per second (MBps). You can only increase your file\n            system's throughput. Valid values are 4000 MBps or multiples of 4000 MBps.</p>"}))
    UpdateFileSystemLustreConfiguration.add_member(:data_read_cache_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LustreReadCacheConfiguration, location_name: 'DataReadCacheConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the optional provisioned SSD read cache on Amazon FSx for Lustre file systems that\n                use the Intelligent-Tiering storage class.</p>"}))
    UpdateFileSystemLustreConfiguration.type = Types::UpdateFileSystemLustreConfiguration
    UpdateFileSystemLustreMetadataConfiguration.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: MetadataIops, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>(USER_PROVISIONED mode only) Specifies the number of Metadata IOPS to provision\n            for your file system.</p>\n         <ul>\n            <li>\n               <p>For SSD file systems, valid values are <code>1500</code>,\n                    <code>3000</code>, <code>6000</code>, <code>12000</code>, and\n                    multiples of <code>12000</code> up to a maximum of <code>192000</code>.</p>\n            </li>\n            <li>\n               <p>For Intelligent-Tiering file systems, valid values are <code>6000</code>\n                    and <code>12000</code>.</p>\n            </li>\n         </ul>\n         <p>The value you provide must be greater than or equal to the current number of\n            Metadata IOPS provisioned for the file system.</p>"}))
    UpdateFileSystemLustreMetadataConfiguration.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: MetadataConfigurationMode, location_name: 'Mode', traits: {"smithy.api#documentation" => "<p>The metadata configuration mode for provisioning Metadata IOPS for\n            an FSx for Lustre file system using a <code>PERSISTENT_2</code>\n            deployment type.</p>\n         <ul>\n            <li>\n               <p>To increase the Metadata IOPS or to switch an SSD file system from\n                    AUTOMATIC,\n                specify <code>USER_PROVISIONED</code> as the value for this parameter. Then use the\n                Iops parameter to provide a Metadata IOPS value that is greater than or equal to\n                the current number of Metadata IOPS provisioned for the file system.</p>\n            </li>\n            <li>\n               <p>To switch from USER_PROVISIONED mode on an SSD file system, specify\n                <code>AUTOMATIC</code> as the value for this parameter, but do not input a value\n                for Iops.</p>\n               <note>\n                  <ul>\n                     <li>\n                        <p>If you request to switch from USER_PROVISIONED to AUTOMATIC mode and the\n                                current Metadata IOPS value is greater than the automated default, FSx for Lustre\n                                rejects the request because downscaling Metadata IOPS is not supported.</p>\n                     </li>\n                     <li>\n                        <p>AUTOMATIC mode is not supported on Intelligent-Tiering\n                                file systems. For Intelligent-Tiering file systems, use USER_PROVISIONED mode.</p>\n                     </li>\n                  </ul>\n               </note>\n            </li>\n         </ul>"}))
    UpdateFileSystemLustreMetadataConfiguration.type = Types::UpdateFileSystemLustreMetadataConfiguration
    UpdateFileSystemOntapConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    UpdateFileSystemOntapConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    UpdateFileSystemOntapConfiguration.add_member(:fsx_admin_password, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminPassword, location_name: 'FsxAdminPassword', traits: {"smithy.api#documentation" => "<p>Update the password for the <code>fsxadmin</code> user by entering a new password. \n        You use the <code>fsxadmin</code> user to access the NetApp ONTAP CLI and REST API to manage your file system resources. \n            For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-resources-ontap-apps.html\">Managing resources using NetApp Application</a>.</p>"}))
    UpdateFileSystemOntapConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    UpdateFileSystemOntapConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS (input output operations per second) configuration for an Amazon FSx for NetApp ONTAP file system. The default is 3 IOPS per GB of storage capacity,\n            but you can provision additional IOPS per GB of storage. The configuration consists\n            of an IOPS mode (<code>AUTOMATIC</code> or <code>USER_PROVISIONED</code>), and in\n            the case of <code>USER_PROVISIONED</code> IOPS, the total number of SSD IOPS provisioned. \n            For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/increase-primary-storage.html\">Updating SSD storage capacity and IOPS</a>.</p>"}))
    UpdateFileSystemOntapConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>Enter a new value to change the amount of throughput capacity for the file system in megabytes per second (MBps). For more information, see \n          <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-throughput-capacity.html\">Managing throughput capacity</a> \n          in the FSx for ONTAP User Guide.</p>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> and <code>ThroughputCapacityPerHAPair</code> are not the same value.</p>\n            </li>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> when divided by the value of <code>HAPairs</code> is outside of the valid range for <code>ThroughputCapacity</code>.</p>\n            </li>\n         </ul>"}))
    UpdateFileSystemOntapConfiguration.add_member(:add_route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'AddRouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) A list of IDs of new virtual private cloud (VPC) route tables\n            to associate (add) with your Amazon FSx for NetApp ONTAP file system.</p>"}))
    UpdateFileSystemOntapConfiguration.add_member(:remove_route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'RemoveRouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) A list of IDs of existing virtual private cloud (VPC)\n            route tables to disassociate (remove) from your Amazon FSx for NetApp ONTAP file system. You can use\n            the  API operation to retrieve the\n            list of VPC route table IDs for a file system.</p>"}))
    UpdateFileSystemOntapConfiguration.add_member(:throughput_capacity_per_ha_pair, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputCapacityPerHAPair, location_name: 'ThroughputCapacityPerHAPair', traits: {"smithy.api#documentation" => "<p>Use to choose the throughput capacity per HA pair, rather than the total throughput for the file system. </p>\n         <p>This field and <code>ThroughputCapacity</code> cannot be defined in the same API call, but one is required.</p>\n         <p>This field and <code>ThroughputCapacity</code> are the same for file systems with one HA pair.</p>\n         <ul>\n            <li>\n               <p>For <code>SINGLE_AZ_1</code> and <code>MULTI_AZ_1</code> file systems, valid values are 128, 256, 512, 1024, 2048, or 4096 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>SINGLE_AZ_2</code>, valid values are 1536, 3072, or 6144 MBps.</p>\n            </li>\n            <li>\n               <p>For <code>MULTI_AZ_2</code>, valid values are 384, 768, 1536, 3072, or 6144 MBps.</p>\n            </li>\n         </ul>\n         <p>Amazon FSx responds with an HTTP status code 400 (Bad Request) for the following conditions:</p>\n         <ul>\n            <li>\n               <p>The value of <code>ThroughputCapacity</code> and <code>ThroughputCapacityPerHAPair</code> are not the same value for file systems with one HA pair.</p>\n            </li>\n            <li>\n               <p>The value of deployment type is <code>SINGLE_AZ_2</code> and <code>ThroughputCapacity</code> / <code>ThroughputCapacityPerHAPair</code> is not a valid HA pair (a value between 1 and 12).</p>\n            </li>\n            <li>\n               <p>The value of <code>ThroughputCapacityPerHAPair</code> is not a valid value.</p>\n            </li>\n         </ul>"}))
    UpdateFileSystemOntapConfiguration.add_member(:ha_pairs, Smithy::Schema::Shapes::ShapeRef.new(shape: HAPairs, location_name: 'HAPairs', traits: {"smithy.api#documentation" => "<p>Use to update the number of high-availability (HA) pairs for a second-generation single-AZ file system. \n            If you increase the number of HA pairs for your file system, you must specify proportional increases for <code>StorageCapacity</code>, \n            <code>Iops</code>, and <code>ThroughputCapacity</code>. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/administering-file-systems.html#HA-pairs\">High-availability (HA) pairs</a> in the FSx for ONTAP user guide. Block storage protocol support \n            (iSCSI and NVMe over TCP) is disabled on file systems with more than 6 HA pairs. For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/supported-fsx-clients.html#using-block-storage\">Using block storage protocols</a>.</p>"}))
    UpdateFileSystemOntapConfiguration.type = Types::UpdateFileSystemOntapConfiguration
    UpdateFileSystemOpenZFSConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays'))
    UpdateFileSystemOpenZFSConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the file system should be copied to\n            backups. This value defaults to <code>false</code>. If it's set to <code>true</code>,\n            all tags for the file system are copied to all automatic and user-initiated backups\n            where the user doesn't specify tags. If this value is <code>true</code> and you specify\n            one or more tags, only the specified tags are copied to backups. If you specify one or\n            more tags when creating a user-initiated backup, no tags are copied from the file\n            system, regardless of this value.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:copy_tags_to_volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToVolumes', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether tags for the volume should be copied to snapshots.\n            This value defaults to <code>false</code>. If it's set to <code>true</code>, all tags\n            for the volume are copied to snapshots where the user doesn't specify tags. If this\n            value is <code>true</code> and you specify one or more tags, only the specified tags are\n            copied to snapshots. If you specify one or more tags when creating the snapshot, no tags\n            are copied from the volume, regardless of this value.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime'))
    UpdateFileSystemOpenZFSConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>The throughput of an Amazon FSx for OpenZFS file system, measured in megabytes per second\u2028 (MB/s). Valid values depend on the DeploymentType you choose, as follows:</p>\n         <ul>\n            <li>\n               <p>For <code>MULTI_AZ_1</code> and <code>SINGLE_AZ_2</code>, valid values are 160, 320, 640,\n                1280, 2560, 3840, 5120, 7680, or 10240 MB/s.</p>\n            </li>\n            <li>\n               <p>For <code>SINGLE_AZ_1</code>, valid values are 64, 128, 256, 512, 1024, 2048, 3072, or 4096 MB/s.</p>\n            </li>\n         </ul>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime'))
    UpdateFileSystemOpenZFSConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration'))
    UpdateFileSystemOpenZFSConfiguration.add_member(:add_route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'AddRouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) A list of IDs of new virtual private cloud (VPC) route tables\n            to associate (add) with your Amazon FSx for OpenZFS file system.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:remove_route_table_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteTableIds, location_name: 'RemoveRouteTableIds', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) A list of IDs of existing virtual private cloud (VPC)\n            route tables to disassociate (remove) from your Amazon FSx for OpenZFS file system. You can use\n            the  API operation to retrieve the\n            list of VPC route table IDs for a file system.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:read_cache_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSReadCacheConfiguration, location_name: 'ReadCacheConfiguration', traits: {"smithy.api#documentation" => "<p>\n            The configuration for the optional provisioned SSD read cache on file systems that use the Intelligent-Tiering storage class.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.add_member(:endpoint_ipv6_address_range, Smithy::Schema::Shapes::ShapeRef.new(shape: Ipv6AddressRange, location_name: 'EndpointIpv6AddressRange', traits: {"smithy.api#documentation" => "<p>(Multi-AZ only) Specifies the IP address range in which the endpoints to access your\n            file system will be created. By default in the Amazon FSx API and Amazon FSx console,\n            Amazon FSx selects an available /118 IP address range for you from one of the VPC's CIDR ranges.\n            You can have overlapping endpoint IP addresses for file systems deployed in the same VPC/route tables,\n            as long as they don't overlap with any subnet.</p>"}))
    UpdateFileSystemOpenZFSConfiguration.type = Types::UpdateFileSystemOpenZFSConfiguration
    UpdateFileSystemRequest.add_member(:file_system_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemId, location_name: 'FileSystemId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the file system that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateFileSystemRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'ClientRequestToken', traits: {"smithy.api#documentation" => "<p>A string of up to 63 ASCII characters that Amazon FSx uses to ensure\n      idempotent updates. This string is automatically filled on your behalf when you use the\n        Command Line Interface (CLI) or an Amazon Web Services SDK.</p>", "smithy.api#idempotencyToken" => {}}))
    UpdateFileSystemRequest.add_member(:storage_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacity, location_name: 'StorageCapacity', traits: {"smithy.api#documentation" => "<p>Use this parameter to increase the storage capacity of an FSx for Windows File Server,\n      FSx for Lustre, FSx for OpenZFS, or FSx for ONTAP file system.\n      Specifies the storage capacity target value, in GiB, to increase the storage capacity for\n      the file system that you're updating. </p>\n         <note>\n            <p>You can't make a storage capacity increase request if there is an existing storage\n        capacity increase request in progress.</p>\n         </note>\n         <p>For Lustre file systems, the storage capacity target value can be the following:</p>\n         <ul>\n            <li>\n               <p>For <code>SCRATCH_2</code>, <code>PERSISTENT_1</code>, and <code>PERSISTENT_2 SSD</code> deployment types, valid values\n        are in multiples of 2400 GiB. The value must be greater than the current storage capacity.</p>\n            </li>\n            <li>\n               <p>For <code>PERSISTENT HDD</code> file systems, valid values are multiples of 6000 GiB for\n        12-MBps throughput per TiB file systems and multiples of 1800 GiB for 40-MBps throughput\n        per TiB file systems. The values must be greater than the current storage capacity.</p>\n            </li>\n            <li>\n               <p>For <code>SCRATCH_1</code> file systems, you can't increase the storage capacity.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/LustreGuide/managing-storage-capacity.html\">Managing storage and throughput\n      capacity</a> in the <i>FSx for Lustre User Guide</i>.</p>\n         <p>For FSx for OpenZFS file systems, the storage capacity target value must be at least 10 percent\n      greater than the current storage capacity value. For more information, see\n      <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/managing-storage-capacity.html\">Managing storage capacity</a> in the <i>FSx for OpenZFS User\n          Guide</i>.</p>\n         <p>For Windows file systems, the storage capacity target value must be at least 10 percent\n      greater than the current storage capacity value. To increase storage capacity, the file system\n      must have at least 16 MBps of throughput capacity. For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/managing-storage-capacity.html\">Managing storage\n        capacity</a> in the <i>Amazon FSxfor Windows File Server User\n          Guide</i>.</p>\n         <p>For ONTAP file systems, the storage capacity target value must be at least 10 percent\n      greater than the current storage capacity value.  For more information, see\n      <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/managing-storage-capacity.html\">Managing storage capacity and provisioned IOPS</a> in the <i>Amazon FSx for NetApp ONTAP User\n          Guide</i>.</p>"}))
    UpdateFileSystemRequest.add_member(:windows_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateFileSystemWindowsConfiguration, location_name: 'WindowsConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration updates for an Amazon FSx for Windows File Server file system.</p>"}))
