    UpdateFileSystemWindowsConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone. Where d is the weekday number, from 1 through 7, with 1 = Monday and 7 = Sunday.</p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime', traits: {"smithy.api#documentation" => "<p>The preferred time to start the daily automatic backup, in the UTC time zone, for example, <code>02:00</code>\n         </p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays', traits: {"smithy.api#documentation" => "<p>The number of days to retain automatic backups. Setting this property to\n            <code>0</code> disables automatic backups. You can retain automatic backups for a\n            maximum of 90 days. The default is <code>30</code>. For more information, see\n            <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/using-backups.html#automatic-backups\">Working with Automatic Daily Backups</a>.</p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>Sets the target value for a file system's throughput capacity, in MB/s, that you are updating the file system to. Valid values are \n            8, 16, 32, 64, 128, 256, 512, 1024, 2048. You cannot make a throughput capacity update request if there is an existing throughput capacity update request in progress. For more information, \n            see <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/managing-throughput-capacity.html\">Managing Throughput Capacity</a>.</p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:self_managed_active_directory_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SelfManagedActiveDirectoryConfigurationUpdates, location_name: 'SelfManagedActiveDirectoryConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration Amazon FSx uses to join the Windows File Server instance to the\n            self-managed Microsoft AD directory. You cannot make a self-managed Microsoft AD update request if there is an existing self-managed Microsoft AD update request in progress.</p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:audit_log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAuditLogCreateConfiguration, location_name: 'AuditLogConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration that Amazon FSx for Windows File Server uses to audit and log\n            user accesses of files, folders, and file shares on the Amazon FSx for Windows File Server\n            file system..</p>"}))
    UpdateFileSystemWindowsConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS (input/output operations per second) configuration for an Amazon FSx for Windows file system.\n            By default, Amazon FSx automatically provisions 3 IOPS per GiB of storage capacity. You can provision additional\n            IOPS per GiB of storage, up to the maximum limit associated with your chosen throughput capacity.</p>"}))
    UpdateFileSystemWindowsConfiguration.type = Types::UpdateFileSystemWindowsConfiguration
    UpdateOntapVolumeConfiguration.add_member(:junction_path, Smithy::Schema::Shapes::ShapeRef.new(shape: JunctionPath, location_name: 'JunctionPath', traits: {"smithy.api#documentation" => "<p>Specifies the location in the SVM's namespace where the volume is mounted. \n            The <code>JunctionPath</code> must have a leading forward slash, such as <code>/vol3</code>.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:security_style, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityStyle, location_name: 'SecurityStyle', traits: {"smithy.api#documentation" => "<p>The security style for the volume, which can be <code>UNIX</code>,\n            <code>NTFS</code>, or <code>MIXED</code>.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:size_in_megabytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacity, location_name: 'SizeInMegabytes', traits: {"smithy.api#documentation" => "<p>Specifies the size of the volume in megabytes.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:storage_efficiency_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'StorageEfficiencyEnabled', traits: {"smithy.api#documentation" => "<p>Default is <code>false</code>. Set to true to enable the deduplication,\n            compression, and compaction storage efficiency features on the volume.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:tiering_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: TieringPolicy, location_name: 'TieringPolicy', traits: {"smithy.api#documentation" => "<p>Update the volume's data tiering policy.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:snapshot_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotPolicy, location_name: 'SnapshotPolicy', traits: {"smithy.api#documentation" => "<p>Specifies the snapshot policy for the volume. There are three built-in snapshot policies:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code>: This is the default policy. A maximum of six hourly snapshots taken five minutes past \n                the hour. A maximum of two daily snapshots taken Monday through Saturday at 10 minutes after\n                midnight. A maximum of two weekly snapshots taken every Sunday at 15 minutes after midnight.</p>\n            </li>\n            <li>\n               <p>\n                  <code>default-1weekly</code>: This policy is the same as the <code>default</code> policy except \n                that it only retains one snapshot from the weekly schedule.</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code>: This policy does not take any snapshots. This policy can be assigned to volumes to \n                prevent automatic snapshots from being taken.</p>\n            </li>\n         </ul>\n         <p>You can also provide the name of a custom policy that you created with the ONTAP CLI or REST API.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snapshots-ontap.html#snapshot-policies\">Snapshot policies</a> \n            in the <i>Amazon FSx for NetApp ONTAP User Guide</i>.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags for the volume should be copied to backups. This value defaults to\n            false. If it's set to true, all tags for the volume are copied to all automatic and user-initiated backups\n            where the user doesn't specify tags. If this value is true, and you specify one or more tags, only the\n            specified tags are copied to backups. If you specify one or more tags when creating a user-initiated\n            backup, no tags are copied from the volume, regardless of this value.</p>"}))
    UpdateOntapVolumeConfiguration.add_member(:snaplock_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateSnaplockConfiguration, location_name: 'SnaplockConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration object for updating the SnapLock configuration of an FSx for ONTAP SnapLock volume. </p>"}))
    UpdateOntapVolumeConfiguration.add_member(:size_in_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeCapacityBytes, location_name: 'SizeInBytes', traits: {"smithy.api#documentation" => "<p>The configured size of the volume, in bytes.</p>"}))
    UpdateOntapVolumeConfiguration.type = Types::UpdateOntapVolumeConfiguration
    UpdateOpenZFSVolumeConfiguration.add_member(:storage_capacity_reservation_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerNoMaxFromNegativeOne, location_name: 'StorageCapacityReservationGiB', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) to reserve from the parent volume.\n            You can't reserve more storage than the parent volume has reserved. You can specify\n            a value of <code>-1</code> to unset a volume's storage capacity reservation.</p>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:storage_capacity_quota_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerNoMaxFromNegativeOne, location_name: 'StorageCapacityQuotaGiB', traits: {"smithy.api#documentation" => "<p>The maximum amount of storage in gibibytes (GiB) that the volume can use from its\n            parent. You can specify a quota larger than the storage on the parent volume. You\n            can specify a value of <code>-1</code> to unset a volume's storage capacity quota.</p>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:record_size_ki_b, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerRecordSizeKiB, location_name: 'RecordSizeKiB', traits: {"smithy.api#documentation" => "<p>Specifies the record size of an OpenZFS volume, in kibibytes (KiB). Valid values are 4, 8,\n            16, 32, 64, 128, 256, 512, or 1024 KiB. The default is 128 KiB.\n            Most workloads should use the default record size. Database workflows can benefit from a smaller \n            record size, while streaming workflows can benefit from a larger record size. For additional guidance on when\n            to set a custom record size, see <a href=\"https://docs.aws.amazon.com/fsx/latest/OpenZFSGuide/performance.html#performance-tips-zfs\">\n                Tips for maximizing performance</a> in the\n            <i>Amazon FSx for OpenZFS User Guide</i>.</p>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:data_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSDataCompressionType, location_name: 'DataCompressionType', traits: {"smithy.api#documentation" => "<p>Specifies the method used to compress the data on the volume. The compression\n            type is <code>NONE</code> by default.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NONE</code> - Doesn't compress the data on the volume.\n                    <code>NONE</code> is the default.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ZSTD</code> - Compresses the data in the volume using the Zstandard\n                    (ZSTD) compression algorithm. Compared to LZ4, Z-Standard provides a better\n                    compression ratio to minimize on-disk storage utilization.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LZ4</code> - Compresses the data in the volume using the LZ4\n                    compression algorithm. Compared to Z-Standard, LZ4 is less compute-intensive\n                    and delivers higher write throughput speeds.</p>\n            </li>\n         </ul>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:nfs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSNfsExports, location_name: 'NfsExports', traits: {"smithy.api#documentation" => "<p>The configuration object for mounting a Network File System (NFS) file system.</p>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:user_and_group_quotas, Smithy::Schema::Shapes::ShapeRef.new(shape: OpenZFSUserAndGroupQuotas, location_name: 'UserAndGroupQuotas', traits: {"smithy.api#documentation" => "<p>An object specifying how much storage users or groups can use on the volume.</p>"}))
    UpdateOpenZFSVolumeConfiguration.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadOnly, location_name: 'ReadOnly', traits: {"smithy.api#documentation" => "<p>A Boolean value indicating whether the volume is read-only.</p>"}))
