    UpdateSnaplockConfiguration.add_member(:audit_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'AuditLogVolume', traits: {"smithy.api#documentation" => "<p>Enables or disables the audit log volume for an FSx for ONTAP SnapLock volume. The default \n        value is <code>false</code>. If you set <code>AuditLogVolume</code> to <code>true</code>, the SnapLock volume is \n        created as an audit log volume. The minimum retention period for an audit log volume is six months. </p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/how-snaplock-works.html#snaplock-audit-log-volume\">\n                SnapLock audit log volumes</a>. </p>"}))
    UpdateSnaplockConfiguration.add_member(:autocommit_period, Smithy::Schema::Shapes::ShapeRef.new(shape: AutocommitPeriod, location_name: 'AutocommitPeriod', traits: {"smithy.api#documentation" => "<p>The configuration object for setting the autocommit period of files in an FSx for ONTAP SnapLock volume. </p>"}))
    UpdateSnaplockConfiguration.add_member(:privileged_delete, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivilegedDelete, location_name: 'PrivilegedDelete', traits: {"smithy.api#documentation" => "<p>Enables, disables, or permanently disables privileged delete on an FSx for ONTAP SnapLock \n            Enterprise volume. Enabling privileged delete allows SnapLock administrators to delete write once, read \n            many (WORM) files even \n            if they have active retention periods. <code>PERMANENTLY_DISABLED</code> is a terminal state. \n        If privileged delete is permanently disabled on a SnapLock volume, you can't re-enable it. The default \n        value is <code>DISABLED</code>. </p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/snaplock-enterprise.html#privileged-delete\">Privileged delete</a>. </p>"}))
    UpdateSnaplockConfiguration.add_member(:retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: SnaplockRetentionPeriod, location_name: 'RetentionPeriod', traits: {"smithy.api#documentation" => "<p>Specifies the retention period of an FSx for ONTAP SnapLock volume. </p>"}))
    UpdateSnaplockConfiguration.add_member(:volume_append_mode_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'VolumeAppendModeEnabled', traits: {"smithy.api#documentation" => "<p>Enables or disables volume-append mode \n            on an FSx for ONTAP SnapLock volume. Volume-append mode allows you to \n            create WORM-appendable files and write data to them incrementally. The default value is <code>false</code>. </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/fsx/latest/ONTAPGuide/worm-state.html#worm-state-append\">Volume-append mode</a>. </p>"}))
    UpdateSnaplockConfiguration.type = Types::UpdateSnaplockConfiguration
