    WindowsAuditLogConfiguration.add_member(:file_access_audit_log_level, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAccessAuditLogLevel, location_name: 'FileAccessAuditLogLevel', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets which attempt type is logged by Amazon FSx for file and folder accesses.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUCCESS_ONLY</code> - only successful attempts to access files\n                    or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILURE_ONLY</code> - only failed attempts to access files\n                    or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCESS_AND_FAILURE</code> - both successful attempts and\n                    failed attempts to access files or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - access auditing of files and folders is turned off.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    WindowsAuditLogConfiguration.add_member(:file_share_access_audit_log_level, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAccessAuditLogLevel, location_name: 'FileShareAccessAuditLogLevel', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets which attempt type is logged by Amazon FSx for file share accesses.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUCCESS_ONLY</code> - only successful attempts to access file\n                    shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILURE_ONLY</code> - only failed attempts to access file\n                    shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCESS_AND_FAILURE</code> - both successful attempts and\n                    failed attempts to access file shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - access auditing of file shares is turned off.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    WindowsAuditLogConfiguration.add_member(:audit_log_destination, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneralARN, location_name: 'AuditLogDestination', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the destination of the audit logs.\n            The destination can be any Amazon CloudWatch Logs log group ARN or\n            Amazon Kinesis Data Firehose delivery stream ARN.</p>\n         <p>The name of the Amazon CloudWatch Logs log group must begin with\n            the <code>/aws/fsx</code> prefix. The name of the Amazon Kinesis Data\n            Firehose delivery stream must begin with the <code>aws-fsx</code> prefix.</p>\n         <p>The destination ARN (either CloudWatch Logs log group or Kinesis\n            Data Firehose delivery stream) must be in the same Amazon Web Services partition,\n            Amazon Web Services Region, and Amazon Web Services account as your Amazon FSx file system.</p>"}))
    WindowsAuditLogConfiguration.type = Types::WindowsAuditLogConfiguration
    WindowsAuditLogCreateConfiguration.add_member(:file_access_audit_log_level, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAccessAuditLogLevel, location_name: 'FileAccessAuditLogLevel', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets which attempt type is logged by Amazon FSx for file and folder accesses.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUCCESS_ONLY</code> - only successful attempts to access files\n                    or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILURE_ONLY</code> - only failed attempts to access files\n                    or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCESS_AND_FAILURE</code> - both successful attempts and\n                    failed attempts to access files or folders are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - access auditing of files and folders is turned off.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    WindowsAuditLogCreateConfiguration.add_member(:file_share_access_audit_log_level, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAccessAuditLogLevel, location_name: 'FileShareAccessAuditLogLevel', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets which attempt type is logged by Amazon FSx for file share accesses.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUCCESS_ONLY</code> - only successful attempts to access file\n                    shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILURE_ONLY</code> - only failed attempts to access file\n                    shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCESS_AND_FAILURE</code> - both successful attempts and\n                    failed attempts to access file shares are logged.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DISABLED</code> - access auditing of file shares is turned off.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    WindowsAuditLogCreateConfiguration.add_member(:audit_log_destination, Smithy::Schema::Shapes::ShapeRef.new(shape: GeneralARN, location_name: 'AuditLogDestination', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) that specifies the destination of the audit logs.</p>\n         <p>The destination can be any Amazon CloudWatch Logs log group ARN or Amazon Kinesis\n            Data Firehose delivery stream ARN, with the following requirements:</p>\n         <ul>\n            <li>\n               <p>The destination ARN that you provide (either CloudWatch Logs log group\n                    or Kinesis Data Firehose delivery stream) must be in the same Amazon Web Services partition,\n                    Amazon Web Services Region, and Amazon Web Services account as your Amazon FSx file system.</p>\n            </li>\n            <li>\n               <p>The name of the Amazon CloudWatch Logs log group must begin with\n                    the <code>/aws/fsx</code> prefix. The name of the Amazon Kinesis Data\n                    Firehose delivery stream must begin with the <code>aws-fsx</code> prefix.</p>\n            </li>\n            <li>\n               <p>If you do not provide a destination in <code>AuditLogDestination</code>,\n                    Amazon FSx will create and use a log stream in the CloudWatch Logs\n                    <code>/aws/fsx/windows</code> log group.</p>\n            </li>\n            <li>\n               <p>If <code>AuditLogDestination</code> is provided and the resource does not\n                    exist, the request will fail with a <code>BadRequest</code> error.</p>\n            </li>\n            <li>\n               <p>If <code>FileAccessAuditLogLevel</code> and <code>FileShareAccessAuditLogLevel</code>\n                    are both set to <code>DISABLED</code>, you cannot specify a destination in\n                    <code>AuditLogDestination</code>.</p>\n            </li>\n         </ul>"}))
