    WindowsFileSystemConfiguration.add_member(:active_directory_id, Smithy::Schema::Shapes::ShapeRef.new(shape: DirectoryId, location_name: 'ActiveDirectoryId', traits: {"smithy.api#documentation" => "<p>The ID for an existing Amazon Web Services Managed Microsoft Active Directory instance that the file system is joined to.</p>"}))
    WindowsFileSystemConfiguration.add_member(:self_managed_active_directory_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SelfManagedActiveDirectoryAttributes, location_name: 'SelfManagedActiveDirectoryConfiguration'))
    WindowsFileSystemConfiguration.add_member(:deployment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsDeploymentType, location_name: 'DeploymentType', traits: {"smithy.api#documentation" => "<p>Specifies the file system deployment type, valid values are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>MULTI_AZ_1</code> - Specifies a high availability file system that is configured for Multi-AZ \n                    redundancy to tolerate temporary Availability Zone (AZ) unavailability, and supports SSD and HDD storage.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_1</code> - (Default) Specifies a file system that is configured for single AZ redundancy, \n                    only supports SSD storage.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SINGLE_AZ_2</code> - Latest generation Single AZ file system. \n                    Specifies a file system that is configured for single AZ redundancy and supports SSD and HDD storage.</p>\n            </li>\n         </ul>\n         <p>For more information, see \n         <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/high-availability-multiAZ.html\">Single-AZ and Multi-AZ File Systems</a>.</p>"}))
    WindowsFileSystemConfiguration.add_member(:remote_administration_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: DNSName, location_name: 'RemoteAdministrationEndpoint', traits: {"smithy.api#documentation" => "<p>For <code>MULTI_AZ_1</code> deployment types, use this endpoint when performing administrative tasks on the file system using \n            Amazon FSx Remote PowerShell.</p>\n         <p>For <code>SINGLE_AZ_1</code> and <code>SINGLE_AZ_2</code> deployment types, this is the DNS name of the file system.</p>\n         <p>This endpoint is temporarily unavailable when the file system is undergoing maintenance.</p>"}))
    WindowsFileSystemConfiguration.add_member(:preferred_subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'PreferredSubnetId', traits: {"smithy.api#documentation" => "<p>For <code>MULTI_AZ_1</code> deployment types, it specifies the ID of the subnet where the preferred file server is located. \n            Must be one of the two subnet IDs specified in <code>SubnetIds</code> property.\n            Amazon FSx serves traffic from this subnet except in the event of a failover to the secondary file server.</p>\n         <p>For <code>SINGLE_AZ_1</code> and <code>SINGLE_AZ_2</code> deployment types, this value is the same as that for <code>SubnetIDs</code>.\n            For more information, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/high-availability-multiAZ.html#single-multi-az-resources\">Availability and durability: Single-AZ and Multi-AZ file systems</a>.</p>"}))
    WindowsFileSystemConfiguration.add_member(:preferred_file_server_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddress, location_name: 'PreferredFileServerIp', traits: {"smithy.api#documentation" => "<p>For <code>MULTI_AZ_1</code> deployment types, the IP address of the primary, or preferred, file server.</p>\n         <p>Use this IP address when mounting the file system on Linux SMB clients or Windows SMB clients that \n            are not joined to a Microsoft Active Directory. \n            Applicable for all Windows file system deployment types. \n            This IP address is temporarily unavailable \n            when the file system is undergoing maintenance. For Linux and Windows \n            SMB clients that are joined to an Active Directory, use the file system's DNSName instead. For more information\n            on mapping and mounting file shares, see \n            <a href=\"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/accessing-file-shares.html\">Accessing File Shares</a>.</p>"}))
    WindowsFileSystemConfiguration.add_member(:throughput_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MegabytesPerSecond, location_name: 'ThroughputCapacity', traits: {"smithy.api#documentation" => "<p>The throughput of the Amazon FSx file system, measured in megabytes per\n            second.</p>"}))
    WindowsFileSystemConfiguration.add_member(:maintenance_operations_in_progress, Smithy::Schema::Shapes::ShapeRef.new(shape: FileSystemMaintenanceOperations, location_name: 'MaintenanceOperationsInProgress', traits: {"smithy.api#documentation" => "<p>The list of maintenance operations in progress for this file system.</p>"}))
    WindowsFileSystemConfiguration.add_member(:weekly_maintenance_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyTime, location_name: 'WeeklyMaintenanceStartTime', traits: {"smithy.api#documentation" => "<p>The preferred start time to perform weekly maintenance, formatted d:HH:MM in the UTC\n            time zone. d is the weekday number, from 1 through 7, beginning with Monday and ending with Sunday.</p>"}))
    WindowsFileSystemConfiguration.add_member(:daily_automatic_backup_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DailyTime, location_name: 'DailyAutomaticBackupStartTime', traits: {"smithy.api#documentation" => "<p>The preferred time to take daily automatic backups, in the UTC time zone.</p>"}))
    WindowsFileSystemConfiguration.add_member(:automatic_backup_retention_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomaticBackupRetentionDays, location_name: 'AutomaticBackupRetentionDays', traits: {"smithy.api#documentation" => "<p>The number of days to retain automatic backups. Setting this to 0 disables automatic\n            backups. You can retain automatic backups for a maximum of 90 days.</p>"}))
    WindowsFileSystemConfiguration.add_member(:copy_tags_to_backups, Smithy::Schema::Shapes::ShapeRef.new(shape: Flag, location_name: 'CopyTagsToBackups', traits: {"smithy.api#documentation" => "<p>A boolean flag indicating whether tags on the file system should be copied to backups.\n            This value defaults to false. If it's set to true, all tags on the file system are\n            copied to all automatic backups and any user-initiated backups where the user\n            doesn't specify any tags. If this value is true, and you specify one or more tags,\n            only the specified tags are copied to backups. If you specify one or more tags when \n            creating a user-initiated backup, no tags are copied from the file system, \n            regardless of this value.</p>"}))
    WindowsFileSystemConfiguration.add_member(:aliases, Smithy::Schema::Shapes::ShapeRef.new(shape: Aliases, location_name: 'Aliases'))
    WindowsFileSystemConfiguration.add_member(:audit_log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WindowsAuditLogConfiguration, location_name: 'AuditLogConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration that Amazon FSx for Windows File Server uses to audit and log\n            user accesses of files, folders, and file shares on the Amazon FSx for Windows File Server\n            file system.</p>"}))
    WindowsFileSystemConfiguration.add_member(:disk_iops_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DiskIopsConfiguration, location_name: 'DiskIopsConfiguration', traits: {"smithy.api#documentation" => "<p>The SSD IOPS (input/output operations per second) configuration for an Amazon FSx for Windows file system.\n            By default, Amazon FSx automatically provisions 3 IOPS per GiB of storage capacity. You can provision additional\n            IOPS per GiB of storage, up to the maximum limit associated with your chosen throughput capacity.</p>"}))
